(window.GioKinhBooks=window.GioKinhBooks||{})["kim-cang"]={"id":"kim-cang","title":"Kinh Kim Cang Bát Nhã Ba La Mật","by":"Việt dịch: HT Thích Trí Tịnh","src":"https://www.daotranglienhoa.com/wp-content/uploads/2022/01/kinh_kim_cang.pdf","srcName":"Đạo Tràng Liên Hoa","chapters":[{"t":"Nguyện Hương","b":[["v",["Nguyện đem lòng thành kính","Gởi theo đám mây hương","Phưởng phất khắp mười phương","Cúng dường ngôi Tam Bảo","Thề trọn đời giữ đạo","Theo tự tánh làm lành","Cùng Pháp giới chúng sanh","Cầu Phật từ gia hộ","Tâm Bồ Đề kiên cố","Chí tu học vững bền","Xa bể khổ nguồn mê","Chóng quay về bờ giác."]]]},{"t":"Tán Phật","b":[["v",["Đấng Pháp Vương vô thượng","Ba cõi chẳng ai bằng","Thầy dạy khắp trời người","Cha lành chung bốn loài","Quy y tròn một niệm","Dứt sạch nghiệp ba kỳ","Xưng dương cùng tán thán","Ức kiếp không cùng tận."]]]},{"t":"Quán Tưởng","b":[["p","Phật, chúng sanh, tánh thường rỗng lặng Đạo cảm thông không thể nghĩ bàn"],["v",["Lưới đế châu ví đạo tràng","Mười phương Phật bảo, hào quang sáng","ngời Trước bảo tọa thân con ảnh hiện","Cúi đầu xin thệ nguyện quy y."]]]},{"t":"Đảnh Lễ","b":[["p","Chí tâm đảnh lễ: Nam mô tận hư không, biến pháp giới, quá, hiện, vị lai thập phương chư Phật, Tôn Pháp, Hiền Thánh Tăng, Thường Trú Tam Bảo. (1 lạy)"],["p","Chí tâm đảnh lễ: Nam mô Ta Bà Giáo Chủ Bổn Sư Thích Ca Mâu Ni Phật, Đương Lai Hạ Sanh Di Lặc Tôn Phật, Đại Trí Văn Thù Sư Lợi Bồ Tát, Đại Hạnh Phổ Hiền Bồ Tát, Hộ Pháp Chư Tôn Bồ Tát, Linh Sơn Hội Thượng Phật Bồ Tát. (1 lạy)"],["p","Chí tâm đảnh lễ: Nam mô Tây Phương Cực Lạc Thế Giới Đại Từ Đại Bi A Di Đà Phật, Đại Bi Quán Thế Âm Bồ Tát, Đại Thế Chí Bồ Tát, Đại Nguyện Địa Tạng Vương Bồ Tát, Thanh Tịnh Đại Hải Chúng Bồ Tát. (1 lạy)"]]},{"t":"Hương Tán","b":[["v",["Lư hương xạ nhiệt","Pháp giới mông huân","Chư Phật hải hội tất diêu văn","Tùy xứ kiết tường vân","Thành ý phương ân","Chư Phật hiện toàn thân."]],["v",["Nam mô Hương Vân Cái Bồ Tát. (3 lần)","TỊNH KHẨU NGHIỆP CHÂN NGÔN","Tu rị, tu rị, ma ha tu rị, tu tu rị, ta bà ha. (3 lần)","TỊNH TAM NGHIỆP CHÂN NGÔN"]],["v",["Án ta phạ, bà phạ, thuật đà ta phạ,","đạt ma ta phạ, bà phạ thuật độ hám. (3 lần)"]],["p","AN THỔ ĐỊA CHÂN NGÔN"],["p","Nam mô tam mãn đa một đà nẫm. Án độ rô độ rô, địa vĩ ta bà ha. (3 lần)"],["p","PHỔ CÚNG DƯỜNG CHÂN NGÔN"],["v",["Án nga nga nẵng, tam bà phạ, phiệt","nhật ra hồng. (3 lần)"]],["h","Phụng Thỉnh Bát Kim Cang"],["v",["Phụng thỉnh Thanh Trừ Tai Kim Cang.","Phụng thỉnh Bích Độc Thần Kim Cang.","Phụng thỉnh Huỳnh Tùy Cầu Kim Cang.","Phụng thỉnh Bạch Tịnh Thủy Kim Cang.","Phụng thỉnh Xích Thanh Hỏa Kim Cang.","Phụng thỉnh Định Trì Tai Kim Cang.","Phụng thỉnh Tử Hiền Kim Cang.","Phụng thỉnh Đại Thần Kim Cang."]],["h","Phụng Thỉnh Tứ Bồ Tát"],["v",["Phụng thỉnh Kim Cang Quyến Bồ tát.","Phụng thỉnh Kim Cang Sách Bồ tát.","Phụng thỉnh Kim Cang Ái Bồ tát.","Phụng thỉnh Kim Cang Ngữ Bồ tát."]]]},{"t":"Phát Nguyện Trì Kinh","b":[["v",["Lạy đấng Tam Giới Tôn","Quy mạng mười phương Phật","Nay con phát nguyện rộng","Trì tụng Kinh Kim Cang","Trên đền bốn ơn nặng","Dưới cứu khổ tam đồ","Nếu có ai thấy nghe","Đều phát tâm Bồ Đề","Khi mãn báo thân này","Sanh qua cõi Cực Lạc."]],["h","Vân Hà Phạm"],["v",["Vân hà đắc trường thọ","Kim cang bất hoại thân","Phục dĩ hà nhân duyên","Đắc đại kiên cố lực","Vân hà ư thử kinh","Cứu cánh đáo bỉ ngạn","Nguyện Phật khai vi mật","Quảng vị chúng sanh thuyết."]],["p","Nam mô Bổn Sư Thích Ca Mâu Ni Phật. (3 lần)"]]},{"t":"Kệ Khai Kinh","b":[["v",["Phật Pháp rộng sâu rất nhiệm mầu","Trăm ngàn muôn kiếp khó tìm cầu","Nay con nghe thấy chuyên trì tụng","Nguyện tỏ Như Lai nghĩa nhiệm mầu."]],["p","Nam mô Bát Nhã Hội Thượng Phật Bồ Tát"],["p","Ma Ha Tát. (3 lần)"]]},{"t":"Phật Nói Kinh Kim Cang Bát Nhã Ba La Mật","b":[["p","(Đời Diêu Tần, Ngài Tam Tạng Pháp Sư Cưu Ma la Thập,"],["p","Hán dịch. Hòa Thượng Thích Trí Tịnh, Việt dịch.)"],["p","Ta nghe như vầy: Một thuở nọ, đức Phật ở trong vườn Kỳ Thọ, Cấp Cô Độc, tại nước Xá Vệ, cùng với chúng đại Tỳ kheo, một nghìn hai trăm năm mươi người câu hội."],["p","Lúc đó, gần đến giờ ăn, đức Thế Tôn đắp y, cầm bát, vào thành lớn Xá Vệ mà khất thực."],["p","Trong thành ấy, đức Phật theo thứ tự, ghé từng nhà, khất thực xong trở về Tịnh Xá, dùng cơm, rồi cất y bát, sau khi rửa chân xong, đức Phật trải tòa mà ngồi."],["p","Bấy giờ, ông Trưởng Lão Tu Bồ Đề, ở trong đại chúng, liền từ chỗ ngồi đứng dậy, trệch áo bên vai hữu, gối bên hữu quỳ sát đất, cung kính chắp tay, mà bạch cùng đức Phật rằng:"],["p","“Hi hữu thay, đức Thế Tôn! Đức Như Lai khéo hay hộ niệm các vị Bồ tát, và khéo hay phó chúc cho các vị Bồ tát!"],["p","“Bạch đức Thế Tôn! Trang thiện nam, người thiện nữ, phát tâm Vô thượng Chánh đẳng Chánh giác, thời phải trụ tâm như thế nào, nên hàng phục tâm mình như thế nào?”"],["p","Đức Phật dạy: “Hay thay! Hay thay!"],["p","Nầy Tu Bồ Đề! Đúng như lời của ông vừa nói, đức Như Lai khéo hay hộ niệm các vị Bồ tát, và khéo hay phó chúc cho các vị Bồ tát."],["p","“Nay ông nên lắng nghe, Ta sẽ vì ông mà nói. Trang thiện nam, người thiện nữ, phát tâm Vô thượng Chánh đẳng Chánh giác, phải trụ tâm như thế nầy, phải hàng phục tâm mình như thế nầy...”"],["p","“Vâng, bạch đức Thế Tôn! Con xin vui thích muốn nghe.”"],["p","Đức Phật bảo ngài Tu Bồ Đề: “Các vị đại Bồ tát phải hàng phục tâm mình như thế này: bao nhiêu những loài chúng sanh, hoặc là loài noãn sanh, hoặc loài thai sanh, hoặc loài thấp sanh, hoặc loài hóa sanh, hoặc loài có hình sắc, hoặc loài không hình sắc, hoặc loài có tư tưởng, hoặc loài không tư tưởng, hoặc loài chẳng phải có tư tưởng, mà cũng chẳng phải không tư tưởng, thời Ta đều làm cho được diệt độ, và đưa tất cả vào nơi vô dư niết bàn. Diệt độ vô lượng, vô số, vô biên chúng sanh như thế, mà thiệt không có chúng sanh nào là kẻ được diệt độ cả. Tại sao vậy? Này, Tu Bồ Đề! Nếu vị Bồ tát còn có tướng ngã, tướng nhân, tướng chúng sanh, tướng thọ giả, thời chẳng phải là Bồ tát."],["p","“Tu Bồ Đề! Lại nữa, vị Bồ tát, đúng nơi pháp, phải nên không có chỗ trụ trước mà làm việc bố thí. Nghĩa là không trụ trước nơi hình sắc mà bố thí, không trụ trước nơi thanh, hương, vị, xúc, pháp, mà bố thí."],["p","“Này, Tu Bồ Đề! Vị Bồ tát phải nên bố thí như thế, chẳng trụ trước nơi tướng."],["p","Tại vì sao? Vì nếu vị Bồ tát, không trụ trước nơi tướng mà bố thí, thời phước đức nhiều không thể suy lường."],["p","“Tu Bồ Đề! Ý của ông nghĩ sao? Có thể suy lường được cõi hư không ở phương đông chăng?”"],["p","“Bạch đức Thế Tôn, không thể suy lường được.”"],["p","“Tu Bồ Đề! Có thể suy lường được cõi hư không ở phương nam, tây, bắc, cõi hư không ở bốn hướng cạnh, và cõi hư không ở trên, dưới, chăng?”"],["p","“Bạch đức Thế Tôn! Không thể suy lường được.”"],["p","“Tu Bồ Đề! Vị Bồ tát không trụ trước nơi tướng mà bố thí, thời phước đức cũng lại như thế, không thể suy lường được."],["p","“Tu Bồ Đề! Vị Bồ tát chỉ phải nên đúng như lời Ta đã dạy đó mà trụ."],["p","“Tu Bồ Đề! Ý của ông nghĩ sao? Có thể do nơi thân tướng mà thấy Như Lai chăng?”"],["p","“Bạch đức Thế Tôn! Không thể do nơi thân tướng mà thấy được Như Lai. Bởi vì sao? Vì đức Như Lai nói thân tướng đó chính là chẳng phải thân tướng.”"],["p","Đức Phật bảo ông Tu Bồ Đề: “Phàm hễ có tướng đều là hư vọng cả! Nếu nhận thấy các tướng đều là không phải tướng, chính là thấy Như Lai.”"],["p","Ông Tu Bồ Đề bạch cùng đức Phật rằng: “Bạch đức Thế Tôn! Như có chúng sanh nào được nghe những câu trong bài giảng giải như vậy, mà sanh lòng tin là thiệt chăng?”"],["p","Đức Phật bảo ông Tu Bồ Đề: “Ông chớ nói lời ấy! Sau khi đức Như Lai diệt độ, năm trăm năm sau, có người trì giới, tu phước, có thể sanh lòng tin nơi những câu trong bài nầy mà cho đó là thiệt, thời phải biết rằng người ấy chẳng phải chỉ vun trồng căn lành từ nơi một đức Phật, hai đức Phật, ba, bốn, năm đức Phật, mà người đó đã vun trồng căn lành từ nơi vô lượng nghìn muôn đức Phật rồi."],["p","“Như có ai nghe những câu trong bài nầy sanh lòng tin trong sạch nhẫn đến chừng trong khoảng một niệm. Tu Bồ Đề!"],["p","Đức Như Lai đều thấy, đều biết, những chúng sanh đó đặng phước đức vô lượng dường ấy. Tại vì sao? Vì những chúng sanh đó không còn có tướng ngã, tướng nhân, tướng chúng sanh, tướng thọ giả, không có tướng pháp, cũng không có tướng phi pháp. Tại vì sao? Vì những chúng sanh đó, nếu trong lòng chấp tướng, thời chính là chấp ngã, nhân, chúng sanh, thọ giả."],["p","“Nếu chấp tướng pháp, thời chính là chấp ngã, nhân, chúng sanh, thọ giả, và vì nếu chấp tướng phi pháp, thời cũng chính là chấp ngã, nhân, chúng sanh, thọ giả, vì thế cho nên, chẳng nên chấp pháp, và cũng chẳng nên chấp phi pháp."],["p","“Cũng bởi nghĩa đó, Như Lai thường dạy rằng: Nầy, các Tỳ kheo, các ông phải biết rằng, pháp của Ta nói ra đó, dụ cũng như thuyền bè, đến pháp còn phải xả bỏ, huống nữa là phi pháp!"],["p","“Tu Bồ Đề! Ý của ông nghĩ thế nào?"],["p","Đức Như Lai có chứng được quả Vô thượng Chánh đẳng Chánh giác chăng?"],["p","Đức Như Lai có nói pháp chăng?”"],["p","Ông Tu Bồ Đề bạch rằng: “Như con hiểu ý nghĩa của Phật nói, thời không có pháp nhứt định nào, gọi là Vô thượng Chánh đẳng Chánh giác, cũng không có pháp nhứt định nào, mà đức Như Lai có thể nói được. Bởi vì sao? Vì pháp của đức Như Lai nói, đều không thể vin lấy, không thể nói được, chẳng phải pháp, chẳng phải ‘không phải pháp’. Tại vì sao? Vì tất cả Hiền Thánh, đều do nơi pháp vô vi mà có từng bực khác nhau.”"],["p","“Tu Bồ Đề! Ý của ông nghĩ thế nào?"],["p","Như có người đem bảy thứ báu, đầy cả cõi tam thiên, đại thiên, để làm việc bố thí, phước đức của người đó đặng, có nhiều hay chăng?”"],["p","Tu Bồ Đề bạch rằng: “Bạch đức Thế Tôn, rất nhiều! Tại làm sao? Vì phước đức đó, chính là không phải thật phước đức, cho nên đức Như Lai nói là phước đức nhiều.”"],["p","“Còn như có người, nơi trong kinh nầy, nhẫn đến thọ trì một bài kệ bốn câu v.v... lại giảng nói cho người khác, thời phước đức nầy trội hơn phước đức trước."],["p","Bởi vì sao? Nầy Tu Bồ Đề! Tất cả các đức Phật, và pháp Vô thượng Chánh đẳng Chánh giác của các đức Phật, đều từ kinh này mà có ra. Nầy Tu Bồ Đề! Phật pháp nói đó chính chẳng phải là Phật pháp."],["p","“Tu Bồ Đề! Vị Tu Đà Hoàn có thể tự nghĩ là mình chứng được quả Tu Đà Hoàn chăng?”"],["p","Ông Tu Bồ Đề bạch rằng: “Bạch đức Thế Tôn, không thể được! Bởi vì sao? Vì vị Tu Đà Hoàn, gọi là bực Nhập Lưu, và chính không nhập vào nơi đâu, chẳng vào sắc, thanh, hương, vị, xúc, pháp, đó gọi là Tu Đà Hoàn.”"],["p","“Tu Bồ Đề! Ý của ông nghĩ thế nào?"],["p","Vị Tư Đà Hàm có thể tự nghĩ rằng mình được quả Tư Đà Hàm chăng?”"],["p","Ông Tu Bồ Đề bạch rằng: “Bạch đức Thế Tôn không thể được! Bởi vì sao? Vì vị Tư Đà Hàm gọi là bực Nhất Vãng Lai, mà thiệt không có vãng lai, đó gọi là Tư Đà Hàm.”"],["p","“Tu Bồ Đề! Ý của ông nghĩ thế nào?"],["p","Vị A Na Hàm có thể tự nghĩ rằng, mình được quả A Na Hàm chăng?”"],["p","Ông Tu Bồ Đề bạch rằng: “Bạch đức Thế Tôn không thể được! Bởi vì sao? Vì vị A Na Hàm gọi là bực Bất Lai, mà thiệt không có tướng bất lai, cho nên gọi là A Na Hàm.”"],["p","“Tu Bồ Đề! Ý của ông nghĩ thế nào?"],["p","Vị A La Hán có thể tự nghĩ rằng, mình chứng được quả vị A La Hán chăng?”"],["p","Ông Tu Bồ Đề bạch rằng: “Bạch đức Thế Tôn không thể được! Bởi vì sao? Vì thiệt không có pháp chi gọi là A La Hán."],["p","Bạch đức Thế Tôn! Nếu như vị A La Hán nghĩ thế nầy: Ta chứng được quả vị A La Hán, thời chính là còn chấp trước tướng ngã, nhân, chúng sanh, thọ giả."],["p","“Bạch đức Thế Tôn! Đức Phật dạy rằng con được môn ‘vô tranh tam muội’, là bực nhứt trong mọi người, là bực A La Hán ly dục thứ nhứt."],["p","“Bạch đức Thế Tôn! Nếu con tự nghĩ rằng mình được quả vị A La Hán, thời chắc đức Thế Tôn chẳng nói: Tu Bồ Đề là người ưa hạnh tịch tịnh. Bởi Tu Bồ Đề thiệt không khởi một niệm, mới gọi Tu Bồ Đề là ưa hạnh tịch tịnh.”"],["p","Đức Phật bảo ông Tu Bồ Đề: “Ý của ông nghĩ thế nào? Thuở xưa, hồi ở chỗ đức Phật Nhiên Đăng, đức Như Lai có chứng đắc nơi pháp chăng?”"],["p","“Bạch đức Thế Tôn! Không. Hồi ở chỗ đức Phật Nhiên Đăng, nơi pháp, đức Như Lai thiệt không có chỗ chứng đắc.”"],["p","“Này, Tu Bồ Đề! Ý của ông nghĩ thế nào? Bồ tát có trang nghiêm Phật độ chăng?”"],["p","“Bạch đức Thế Tôn! Không, tại vì sao? Vì trang nghiêm Phật độ đó, chính chẳng phải trang nghiêm, đó tạm gọi là trang nghiêm.”"],["p","“Này, Tu Bồ Đề! Vì thế các vị đại Bồ tát, phải nên sanh tâm thanh tịnh như vầy: chẳng nên trụ trước nơi sắc mà sanh tâm, chẳng nên trụ trước nơi thanh, hương, vị, xúc, và pháp, mà sanh tâm, nên ‘không chỗ trụ trước’ mà sanh tâm thanh tịnh kia."],["p","“Này, Tu Bồ Đề! Ví như có người, thân như núi chúa Tu Di, ý của ông nghĩ thế nào? Thân của người đó, có lớn chăng?”"],["p","Ông Tu Bồ Đề bạch rằng: “Bạch đức Thế Tôn! Rất lớn. Bởi vì sao? Vì đức Phật nói chẳng phải thân, đó mới gọi là thân lớn.”"],["p","“Tu Bồ Đề! Như trong một sông Hằng có bao nhiêu số cát, lại có những sông Hằng nhiều như số cát đó. Ý của ông nghĩ thế nào? Số cát trong những sông Hằng đó, chừng có nhiều chăng?”"],["p","Ông Tu Bồ Đề bạch rằng: “Bạch đức Thế Tôn! Rất nhiều. Nội những sông Hằng đã là nhiều vô số rồi, huống nữa là số cát trong sông!”"],["p","“Này, Tu Bồ Đề! Nay Ta nói thật mà bảo ông: Nếu có trang nam tử, thiện nữ nhơn nào đem bảy thứ báu đầy cả ngần ấy Hằng hà sa số cõi Tam thiên đại thiên để làm việc bố thí, người đó đặng phước có nhiều không?”"],["p","Ông Tu Bồ Đề bạch rằng: “Bạch đức Thế Tôn! Rất nhiều.”"],["p","Đức Phật bảo ông Tu Bồ Đề: “Nơi trong kinh này, nếu có trang thiện nam, người thiện nữ nào, thọ trì nhẫn đến một bài kệ bốn câu v.v... và giảng nói cho người khác nghe, thời phước đức này hơn phước đức trước kia."],["p","“Nầy Tu Bồ Đề! Lại nữa, tùy chỗ nào giảng nói kinh nầy, nhẫn đến một bài kệ bốn câu v.v... phải biết chỗ đó, tất cả Trời, Người, A Tu La... trong đời, đều nên cúng dường như là tháp miếu thờ đức Phật."],["p","Huống nữa là, có người nào hay thọ trì, đọc tụng, trọn cả kinh nầy!"],["p","“Nầy Tu Bồ Đề! Phải biết người ấy thành tựu pháp tối thượng, hy hữu bực nhứt."],["p","“Còn nếu kinh điển nầy ở tại chỗ nào, thời chỗ đó chính là có đức Phật, hoặc có hàng tôn trọng Đệ Tử của Phật.”"],["p","Bấy giờ, ông Tu Bồ Đề bạch đức Phật rằng: “Bạch đức Thế Tôn! Tên gọi kinh nầy là gì? Chúng con phải phụng trì thế nào?”"],["p","Đức Phật bảo ông Tu Bồ Đề rằng: “Kinh nầy tên là Kim Cang Bát Nhã Ba La Mật, ông nên theo danh tự ấy mà phụng trì."],["p","“Bởi vì sao? Nầy Tu Bồ Đề, đức Phật nói Bát nhã Ba la mật, chính chẳng phải Bát nhã ba la mật, đó gọi là Bát nhã Ba la mật."],["v",["“Tu Bồ Đề! Ý của ông nghĩ thế nào?","Đức Như Lai có chỗ nào nói pháp chăng?”"]],["p","Ông Tu Bồ Đề bạch Phật rằng: “Bạch đức Thế Tôn! Đức Như Lai không có chỗ nào nói pháp.”"],["p","“Tu Bồ Đề! Ý của ông nghĩ thế nào?"],["p","Bao nhiêu vi trần trong cõi tam thiên, đại thiên, thế là nhiều chăng?”"],["p","Ông Tu Bồ Đề bạch rằng: “Bạch đức Thế Tôn! Rất nhiều.”"],["p","“Nầy Tu Bồ Đề! Những vi trần ấy, đức Như Lai nói chẳng phải vi trần, đó tạm gọi là vi trần. Đức Như Lai nói thế giới cũng chẳng phải thế giới, chỉ tạm gọi là thế giới."],["p","“Nầy Tu Bồ Đề! Nơi ý của ông nghĩ thế nào? Có thể do ba mươi hai tướng mà thấy Như Lai chăng?”"],["p","“Bạch đức Thế Tôn! Không. Chẳng có thể do ba mươi hai tướng mà thấy được Như Lai."],["p","“Bởi vì sao? Đức Như Lai nói ba mươi hai tướng chính chẳng phải tướng, đó chỉ tạm gọi tên là ba mươi hai tướng.”"],["p","“Tu Bồ Đề! Như có trang thiện nam, người thiện nữ nào, đem thân mạng, bằng số cát sông Hằng ra bố thí. Nếu lại có người giữ theo trong kinh nầy, mà thọ trì nhẫn đến những bài kệ bốn câu v.v... mà giảng nói cho người khác nghe, thời phước của người nầy nhiều hơn người trên.”"],["p","Bấy giờ, ông Tu Bồ Đề nghe đức Phật nói kinh nầy, thời ông hiểu thấu nghĩa thú của kinh, nên ông buồn khóc, rơi lệ mà bạch với đức Phật rằng:"],["p","“Hi hữu thay, đức Thế Tôn! Đức Phật nói kinh điển rất sâu xa dường ấy, từ ngày trước khi đặng huệ nhãn đến nay, con chưa từng được nghe kinh điển như thế nầy."],["p","“Bạch đức Thế Tôn! Nếu lại có người được nghe kinh nầy, mà có lòng tin thanh tịnh, thời chính là sanh thiệt tướng. Phải biết người ấy thành tựu công đức hi hữu bực nhất."],["p","“Bạch đức Thế Tôn! Thiệt tướng đó chính chẳng phải tướng, cho nên đức Như Lai gọi là thiệt tướng."],["p","“Bạch đức Thế Tôn! Nay con được nghe kinh điển như thế nầy, con tin hiểu, thọ trì, chẳng đủ lấy làm khó."],["p","“Nếu khoảng năm trăm năm rốt sau ở đời tương lai, mà có chúng sanh nào đặng nghe kinh nầy, rồi tin hiểu thọ trì, thời người ấy chính là hi hữu bực nhứt."],["p","“Bởi vì sao? Người ấy không có tướng ngã, không có tướng nhân, không có tướng chúng sanh, không có tướng thọ giả."],["p","“Vì sao thế? Vì tướng ngã chính là không phải tướng, tướng nhân, tướng chúng sanh, tướng thọ giả, chính là không phải tướng!"],["p","“Bởi vì sao? Vì rời lìa tất cả tướng, chính đó gọi là chư Phật.”"],["p","Đức Phật bảo ông Tu Bồ Đề: “Đúng thế! Đúng thế! Lại như có người được nghe kinh nầy mà lòng không kinh hãi, không e sợ, không nhút nhát, thời phải biết, người đó rất là hi hữu. Bởi vì sao?"],["p","Nầy Tu Bồ Đề! Đức Như Lai nói môn Ba la mật thứ nhất chính chẳng phải môn Ba la mật thứ nhất, đó tạm gọi là môn Ba la mật thứ nhất."],["p","“Tu Bồ Đề! Môn Nhẫn nhục Ba la mật, đức Như Lai nói đó chẳng phải Nhẫn nhục Ba la mật, mà tạm gọi là Nhẫn nhục Ba la mật."],["p","“Bởi vì sao? Nầy Tu Bồ Đề! Như Ta thuở xưa, bị vua Ca Lợi chặt đứt thân thể."],["p","Trong lúc đó, Ta không có tướng ngã, không có tướng nhân, không có tướng chúng sanh, không có tướng thọ giả."],["p","“Vì sao vậy? Vì thuở xưa, trong lúc thân phận bị chặt rời rã đó, nếu Ta còn có tướng ngã, tướng nhân, tướng chúng sanh, tướng thọ giả, thời lẽ ra Ta khởi lòng hờn giận."],["p","“Nầy Tu Bồ Đề! Ta lại nhớ hồi thuở quá khứ, trong năm trăm đời, Ta làm vị Tiên nhẫn nhục. Trong bao nhiêu đời đó, Ta không tướng ngã, không tướng nhân, không tướng chúng sanh, không tướng thọ giả."],["p","“Tu Bồ Đề! Vì thế nên, Bồ tát phải rời lìa tất cả tướng, phát tâm Vô thượng Chánh đẳng Chánh giác. Chẳng nên trụ trước nơi sắc mà sanh tâm, chẳng nên trụ trước nơi thanh, hương, vị, xúc, pháp, mà sanh tâm. Nên sanh tâm không trụ trước vào đâu cả."],["p","“Nếu như tâm còn có chỗ để trụ, thời chính là chẳng phải trụ, cho nên đức Phật nói, tâm của Bồ tát chẳng nên trụ trước nơi sắc mà bố thí."],["p","“Nầy Tu Bồ Đề! Bồ tát vì lợi ích cho tất cả chúng sanh, nên phải bố thí như thế. Đức Như Lai nói tất cả các tướng chính là không phải tướng, lại nói tất cả chúng sanh chính là chẳng phải chúng sanh."],["p","“Nầy Tu Bồ Đề! Đức Như Lai là bực nói lời chân chánh, lời chắc thiệt, lời đứng đắn, lời không phỉnh phờ, lời không sai khác."],["p","“Nầy Tu Bồ Đề! Pháp của đức Như Lai chứng đặng, pháp ấy, không thiệt, không hư."],["p","“Nầy Tu Bồ Đề! Nếu tâm của Bồ tát trụ trước nơi pháp mà làm việc bố thí, thời như người vào chỗ tối tăm, liền không thấy đặng chi cả."],["p","“Nếu tâm của Bồ tát, không trụ trước nơi pháp mà làm việc bố thí, thời như người có mắt sáng, lại có ánh sáng của mặt trời chiếu đến liền thấy các thứ hình sắc."],["p","“Nầy Tu Bồ Đề! Về đời đương lai, nếu có trang thiện nam, người thiện nữ nào, có thể thọ trì, đọc tụng kinh nầy, liền được đức Như Lai dùng trí huệ của Phật, đều biết rõ người ấy, đều thấy rõ người ấy, thảy đều được thành tựu công đức vô lượng, vô biên."],["p","“Nầy Tu Bồ Đề! Nếu có trang thiện nam, người thiện nữ nào, vào khoảng buổi sáng, đem thân mạng bằng số cát sông Hằng để bố thí, vào khoảng buổi trưa, lại đem thân mạng bằng số cát sông Hằng để bố thí, vào khoảng buổi chiều cũng đem thân mạng, bằng số cát sông Hằng để bố thí; trong vô lượng trăm nghìn muôn ức kiếp, đem thân mạng bố thí như thế."],["p","“Lại như có người nào, nghe kinh điển nầy mà sanh lòng tin không trái, thời phước của người nầy, hơn phước của người trước kia, huống chi là biên chép, thọ trì, đọc tụng, nói cho người khác nghe!"],["p","“Nầy Tu Bồ Đề! Tóm tắt mà nói đó, thời kinh nầy có vô biên công đức không thể nghĩ bàn, không thể cân lường được."],["p","“Đức Như Lai vì người phát tâm đại thừa mà nói, vì người phát tâm tối thượng thừa mà nói."],["p","“Như có người nào, có thể thọ trì, đọc tụng, giảng nói rộng ra cho người khác nghe, thời đức Như Lai đều biết rõ người ấy, đều thấy rõ người ấy, thảy đều được thành tựu công đức không thể lường được, không thể cân được, không có ngằn mé, không thể nghĩ bàn được."],["p","“Những người như thế, chính là người gánh vác pháp Vô thượng Chánh đẳng Chánh giác của đức Như Lai."],["p","“Bởi vì sao? Nầy Tu Bồ Đề! Vì nếu người nào ham ưa pháp tiểu thừa, chấp trước tướng ngã, tướng nhân, tướng chúng sanh, tướng thọ giả, thời ở nơi kinh nầy, người ấy không thể nghe nhận, đọc tụng và giảng nói cho người khác nghe được."],["p","“Nầy Tu Bồ Đề! Nếu những nơi chỗ nào mà có kinh nầy, thời tất cả Trời, người, A Tu La..., trong đời đều nên cúng dường. Phải biết chỗ đó chính là tháp thờ đức Phật, đều phải cung kính lễ lạy, đi nhiễu quanh, đem các món hoa hương mà rải trên chỗ đó."],["p","“Lại nữa, nầy Tu Bồ Đề! Như có trang nam tử, thiện nữ nhân nào, thọ trì, đọc tụng, kinh nầy, lại bị người khinh tiện thì những tội nghiệp đã gây ra trong đời trước, người ấy đáng lẽ sẽ phải đọa vào ác đạo, nhưng bởi trong đời nay, bị người khinh tiện, nên tội nghiệp đã gây ra trong đời trước đó, liền được tiêu diệt, người ấy sẽ đặng đạo Vô thượng Chánh đẳng Chánh giác."],["p","“Nầy Tu Bồ Đề! Ta nhớ lại hồi thuở trước đức Phật Nhiên Đăng ra đời, vô lượng vô số kiếp về quá khứ, Ta gặp đặng tám trăm bốn nghìn muôn ức na do tha các đức Phật, lúc ấy Ta thảy đều hầu hạ, cúng dường, không có luống bỏ qua."],["p","“Về đời mạt thế sau nầy, nếu có người hay thọ trì, đọc tụng kinh nầy, thời công đức của những người ấy có được, nếu đem so sánh với công đức cúng dường các đức Phật của Ta trong thuở trước, thời công đức của Ta sánh không bằng một phần trăm, một phần nghìn, muôn, ức, cho đến tính đếm thí dụ đều chẳng bằng được."],["p","“Nầy Tu Bồ Đề! Về đời mạt thế sau nầy, nếu có trang thiện nam, người thiện nữ nào, thọ trì, đọc tụng, kinh nầy, công đức của những người đây đặng, nếu Ta nói đủ hết cả ra, hoặc có kẻ nghe đó, trong lòng liền cuồng loạn, nghi ngờ, không tin."],["p","“Nầy Tu Bồ Đề! Phải biết rằng, vì nghĩa lý của kinh nầy chẳng thể nghĩ bàn được, nên quả báo cũng không thể nghĩ bàn được!”"],["p","Bấy giờ, ông Tu Bồ Đề bạch với đức Phật: “Bạch đức Thế Tôn! Trang thiện nam, người thiện nữ, phát tâm Vô thượng Chánh đẳng Chánh giác, phải trụ tâm như thế nào? Phải hàng phục tâm mình như thế nào?”"],["p","Đức Phật bảo ông Tu Bồ Đề: “Trang thiện nam, người thiện nữ, phát tâm Vô thượng Chánh đẳng Chánh giác đó, thời phải sanh tâm như vầy: Ta phải diệt độ tất cả chúng sanh, diệt độ tất cả chúng sanh xong, mà không có một chúng sanh nào thiệt diệt độ."],["p","“Bởi vì sao? Nầy Tu Bồ Đề! Nếu Bồ tát mà còn có tướng ngã; tướng nhân, tướng chúng sanh, tướng thọ giả thời chính là chẳng phải Bồ tát."],["p","“Vì cớ sao? Nầy Tu Bồ Đề! Vì thiệt ra không có pháp chi phát tâm Vô thượng Chánh đẳng Chánh giác cả?"],["p","“Nầy Tu Bồ Đề, nơi ý của Ông nghĩ thế nào? Ở nơi chỗ đức Phật Nhiên Đăng thì Như Lai có pháp chi mà được thành Vô thượng Chánh đẳng Chánh giác chăng?”"],["p","“Bạch đức Thế Tôn! Không, như chỗ con hiểu nghĩa lý của lời Phật dạy, thời ở nơi đức Phật Nhiên Đăng, Đức Thế Tôn đã không có pháp chi mà được thành Vô thượng Chánh đẳng Chánh giác cả.”"],["p","Đức Phật dạy rằng: “Đúng thế! Đúng thế! Nầy Tu Bồ Đề! Thiệt không có pháp chi đức Như Lai đặng Vô thượng Chánh đẳng Chánh giác."],["p","“Nầy Tu Bồ Đề! Nếu còn có pháp nào mà đức Như Lai được Vô thượng Chánh đẳng Chánh giác, thời đức Phật Nhiên Đăng bèn chẳng thọ ký cho Ta rằng: ‘Ông ở đời sau sẽ được thành Phật hiệu là Thích Ca Mâu Ni.’"],["p","“Bởi thiệt không có pháp chi để được Vô thượng Chánh đẳng Chánh giác, cho nên đức Phật Nhiên Đăng đã thọ ký cho Ta, mà nói lời nầy:"],["p","‘Ông ở đời sau sẽ được thành Phật hiệu là Thích Ca Mâu Ni.’ Bởi vì sao? Vì Như Lai đó chính là nghĩa các pháp như như."],["p","“Nếu có người nói rằng: Đức Như Lai được thành Vô thượng Chánh đẳng Chánh giác."],["p","“Nầy Tu Bồ Đề! Thiệt ra không có pháp chi mà đức Phật được Vô thượng Chánh đẳng Chánh giác."],["p","“Nầy Tu Bồ Đề! Vô thượng Chánh đẳng Chánh giác của đức Như Lai chứng được, trong đó không thiệt, không hư, vì thế đức Như Lai nói, tất cả pháp đều là Phật pháp."],["p","“Nầy Tu Bồ Đề! Tất cả pháp mà đức Phật nói đó, chính chẳng phải tất cả pháp, cho nên gọi là tất cả pháp."],["p","“Nầy Tu Bồ Đề! Ví như thân người cao lớn.”"],["p","Ông Tu Bồ Đề bạch rằng: “Bạch đức Thế Tôn! Đức Như Lai nói thân người cao lớn, chính là chẳng phải thân cao lớn, đó tạm gọi là thân cao lớn.”"],["p","“Nầy Tu Bồ Đề! Bồ tát cũng như thế."],["p","Nếu nói lời như vầy: Ta sẽ diệt độ vô lượng chúng sanh, thời vị đó không gọi là bực Bồ tát."],["p","“Bởi vì sao? Nầy Tu Bồ Đề! Thiệt không có pháp chi gọi là Bồ tát."],["p","“Vì thế, Như Lai nói tất cả pháp, không ngã, không nhân, không chúng sanh, không thọ giả."],["p","“Nầy Tu Bồ Đề! Nếu Bồ tát nói như thế nầy: Ta phải trang nghiêm Phật độ, thời vị ấy không gọi là bực Bồ tát."],["p","“Bởi vì sao? Vì Như Lai nói trang nghiêm Phật độ đó, chính chẳng phải trang nghiêm, đó tạm gọi là trang nghiêm."],["p","“Nầy Tu Bồ Đề! Nếu Bồ tát thông đạt được lý không ngã, không pháp đó, thời Như Lai gọi là thiệt phải bực Bồ tát."],["p","“Nầy Tu Bồ Đề! Nơi ý của ông nghĩ thế nào? Đức Như Lai có nhục nhãn chăng?”"],["p","“Bạch đức Thế Tôn! Đúng thế, đức Như Lai có nhục nhãn.”"],["p","“Nầy Tu Bồ Đề! Nơi ý của ông nghĩ thế nào? Đức Như Lai có thiên nhãn chăng?”"],["p","“Bạch đức Thế Tôn! Đúng thế. Đức Như Lai có thiên nhãn.”"],["p","“Nầy Tu Bồ Đề! Nơi ý của ông nghĩ thế nào? Đức Như Lai có huệ nhãn chăng?”"],["p","“Bạch đức Thế Tôn! Đúng thế. Đức Như Lai có huệ nhãn.”"],["p","“Nầy Tu Bồ Đề! Nơi ý của ông nghĩ thế nào? Đức Như Lai có pháp nhãn chăng?”"],["p","“Bạch đức Thế Tôn! Đúng thế. Đức Như Lai có pháp nhãn.”"],["p","“Nầy Tu Bồ Đề! Nơi ý của ông nghĩ thế nào? Đức Như Lai có Phật nhãn chăng?”"],["p","“Bạch đức Thế Tôn! Đúng thế. Đức Như Lai có Phật nhãn.”"],["p","“Nầy Tu Bồ Đề! Nơi ý của ông nghĩ thế nào? Như bao nhiêu cát trong sông Hằng, đức Phật có nói là cát chăng?”"],["p","“Bạch đức Thế Tôn! Đúng thế, đức Như Lai nói là cát.”"],["p","“Nầy Tu Bồ Đề! Nơi ý của ông nghĩ thế nào? Ví như có bao nhiêu cát trong một sông Hằng, thì cũng có số những sông Hằng, bằng số cát như thế, cõi Phật như bao nhiêu số cát trong những sông Hằng đó, như thế, cõi Phật có nhiều chăng?”"],["p","“Bạch đức Thế Tôn! Rất nhiều!”"],["p","Đức Phật bảo ông Tu Bồ Đề: “Bao nhiêu thứ tâm niệm của tất cả chúng sanh trong ngần ấy cõi nước, đức Như Lai đều biết rõ. Bởi vì sao? Vì đức Như Lai nói các thứ tâm đều là chẳng phải tâm, đó gọi là tâm. Vì cớ sao thế? Nầy Tu Bồ Đề! Tâm quá khứ không có chi mà đặng, tâm hiện tại không có chi mà đặng, tâm vị lai không có chi mà đặng."],["p","“Nầy Tu Bồ Đề! Nơi ý của ông nghĩ thế nào? Như có người đem bảy thứ báu, đầy cả cõi tam thiên đại thiên để dùng bố thí. Do nhơn duyên như thế, người ấy có được phước, có nhiều chăng?”"],["p","“Bạch đức Thế Tôn! Đúng thế. Người đó, do nhân duyên ấy, được phước rất nhiều.”"],["p","“Nầy Tu Bồ Đề! Nếu dùng phước đức là có, hữu vi, thì đức Như Lai chẳng nói là được phước đức nhiều. Do vì phước đức là không, vô vi, nên đức Như Lai mới nói là được phước đức nhiều.”"],["p","“Nầy Tu Bồ Đề! Nơi ý ông nghĩ thế nào? Có thể do sắc thân cụ túc, mà thấy được đức Phật chăng?”"],["p","“Bạch đức Thế Tôn! Không. Chẳng nên do sắc thân cụ túc mà thấy được đức Như Lai. Bởi vì sao? Vì đức Như Lai nói sắc thân cụ túc, chính chẳng phải sắc thân cụ túc, đó tạm gọi là sắc thân cụ túc.”"],["p","“Nầy Tu Bồ Đề! Nơi ý ông nghĩ thế nào? Có thể do nơi các tướng cụ túc mà thấy được đức Như Lai chăng?”"],["p","“Bạch đức Thế Tôn! Không. Chẳng nên do nơi các tướng cụ túc mà thấy được đức Như Lai. Bởi vì sao? Vì đức Như Lai nói các tướng cụ túc, nhưng chẳng phải cụ túc, đó tạm gọi là các tướng cụ túc.”"],["p","“Nầy Tu Bồ Đề! Ông chớ nói rằng đức Như Lai nghĩ thế nầy: Ta nên có chỗ thuyết pháp, ông đừng nghĩ như thế. Bởi vì sao? Vì nếu người nào nói rằng: Đức Như Lai có thuyết pháp, thời là hủy báng đức Phật, không hiểu được nghĩa lý của Phật nói."],["p","“Nầy Tu Bồ Đề! Thuyết pháp đó chính thiệt không có pháp chi nói được, đó tạm gọi là thuyết pháp.”"],["p","Bấy giờ, ông Huệ Mạng Tu Bồ Đề bạch đức Phật rằng: “Bạch đức Thế Tôn!"],["p","Trong thời vị lai, chừng có chúng sanh nào nghe nói pháp nầy mà sanh lòng tin chăng?”"],["p","Đức Phật dạy rằng: “Nầy Tu Bồ Đề!"],["p","Chúng sanh kia chẳng phải chúng sanh, cũng chẳng phải là không phải chúng sanh. Bởi vì sao? Nầy Tu Bồ Đề! Những chúng sanh, chúng sanh đó, đức Như Lai nói chẳng phải chúng sanh, đó tạm gọi là chúng sanh.”"],["p","Ông Tu Bồ Đề bạch với đức Phật rằng: “Bạch đức Thế Tôn! Đức Phật chứng được Vô thượng Chánh đẳng Chánh giác là không có chỗ chi là được sao?”"],["p","Đức Phật dạy rằng: “Đúng thế! Đúng thế! Nầy Tu Bồ Đề! Ta ở nơi Vô thượng Chánh đẳng Chánh giác, nhẫn đến không có chút pháp chi có thể gọi là được đó mới gọi là Vô thượng Chánh đẳng Chánh giác.”"],["p","“Lại nữa, nầy Tu Bồ Đề! Pháp đó bình đẳng, không có cao, thấp, đó gọi là Vô thượng Chánh đẳng Chánh giác."],["p","“Do vì không ngã, không nhơn, không chúng sanh, không thọ giả, mà tu tất cả pháp lành, liền được Vô thượng Chánh đẳng Chánh giác."],["p","“Nầy Tu Bồ Đề! Pháp lành đã nói đó đức Như Lai nói chính chẳng phải pháp lành đó tạm gọi là pháp lành."],["p","“Nầy Tu Bồ Đề! Như trong cõi tam thiên, đại thiên, có bao nhiêu núi chúa Tu Di, nếu có người góp cả bảy thứ báu lại, bằng những núi Tu Di đó, đem dùng mà bố thí."],["p","“Nơi kinh Bát Nhã Ba La Mật nầy nhẫn đến một bài kệ bốn câu v.v... nếu có người thọ trì, đọc tụng, giảng nói cho kẻ khác nghe, thời phước đức của người bố thí trước, sánh không bằng một phần trăm, một phần nghìn, muôn ức, cho đến tính đếm thí dụ đều chẳng bằng được."],["p","“Nầy Tu Bồ Đề! Nơi ý của ông nghĩ thế nào? Các ông chớ cho rằng đức Như Lai nghĩ như vầy: Ta phải hóa độ chúng sanh. Nầy Tu Bồ Đề! Ông đừng nghĩ như thế. Bởi vì sao? Vì thiệt không có chúng sanh nào đức Như Lai độ cả. Nếu có chúng sanh mà đức Như Lai độ đó, thời đức Như Lai còn có tướng ngã, nhơn, chúng sanh, thọ giả."],["p","“Nầy Tu Bồ Đề! Đức Như Lai nói có ngã đó chính chẳng phải có ngã, mà kẻ phàm phu lại cho là có ngã."],["p","“Nầy Tu Bồ Đề! Phàm phu đó, đức Như Lai nói chính chẳng phải phàm phu, đó tạm gọi là phàm phu."],["p","“Nầy Tu Bồ Đề! Nơi ý của ông nghĩ thế nào? Có thể do nơi ba mươi hai tướng mà xem là đức Như Lai chăng?”"],["p","Ông Tu Bồ Đề bạch rằng: “Đúng thế!"],["p","Đúng thế! Do nơi ba mươi hai tướng mà xem là đức Như Lai.”"],["p","Đức Phật dạy rằng: “Nầy Tu Bồ Đề!"],["p","Nếu do nơi ba mươi hai tướng mà xem là đức Như Lai đó, thời vua Chuyển Luân Thánh Vương chính là đức Như Lai rồi!”"],["p","Ông Tu Bồ Đề bạch với đức Phật rằng: “Bạch đức Thế Tôn! Theo như con hiểu nghĩa lý của đức Phật nói, thời chẳng nên do nơi ba mươi hai tướng mà xem là đức Như Lai.” Bấy giờ đức Thế Tôn liền nói kệ rằng:"],["v",["“Nếu dùng sắc thấy ta,","“Dùng tiếng tăm cầu ta,","“Người ấy tu đạo tà!","“Chẳng thấy được Như Lai.","“Tu Bồ Đề! Nếu ông nghĩ thế nầy:"]],["p","Đức Như Lai, không phải vì có tướng cụ túc mà được Vô thượng Chánh đẳng Chánh giác!"],["p","“Tu Bồ Đề! Ông cũng đừng nghĩ như vầy: Đức Như Lai há chẳng do nơi tướng cụ túc mà được Vô thượng Chánh đẳng Chánh giác sao?"],["p","“Tu Bồ Đề! Nếu ông nghĩ như vầy:"],["p","Người phát tâm Vô thượng Chánh đẳng Chánh giác nói các pháp đều đoạn diệt."],["p","Ông đừng nghĩ như thế. Bởi vì sao? Vì nơi các pháp, người phát tâm Vô thượng Chánh đẳng Chánh giác không nói tướng đoạn diệt."],["p","“Nầy Tu Bồ Đề! Nếu Bồ tát đem bảy thứ báu đầy cả những cõi nước bằng số cát sông Hằng để làm việc bố thí."],["p","“Nếu lại có người biết lý vô ngã của tất cả pháp mà đặng thành nhẫn trí. Vị Bồ tát nầy được công đức hơn phước đức của vị Bồ tát trước. Bởi vì sao? Nầy Tu Bồ Đề! Vì các vị Bồ tát không nhận lấy phước đức.”"],["p","Ông Tu Bồ Đề bạch với đức Phật rằng: “Bạch đức Thế Tôn! Tại sao các vị Bồ tát không nhận lấy phước đức?”"],["p","“Nầy Tu Bồ Đề! Vị Bồ tát phàm có làm việc phước đức thời chẳng nên tham trước, vì thế nên nói là chẳng nhận lấy phước đức."],["p","“Nầy Tu Bồ Đề! Nếu có người nói:"],["p","Đức Như Lai hoặc đến, hoặc đi, hoặc ngồi, hoặc nằm, thời người ấy không hiểu nghĩa của Phật nói. Bởi vì sao? Vì Như Lai đó, không từ nơi nào lại, mà cũng không đi về đâu, nên gọi là Như Lai!"],["p","“Nầy Tu Bồ Đề! Như có trang thiện nam, người thiện nữ, đem cõi tam thiên đại thiên đập nát ra vi trần. Nơi ý ông nghĩ thế nào? Các vi trần đó có nhiều chăng?”"],["p","Ông Tu Bồ Đề bạch rằng: “Bạch đức Thế Tôn! Rất nhiều. Bởi vì sao? Vì nếu những vi trần đó là thiệt có, thời đức Phật chẳng nói là những vi trần."],["p","“Vì cớ sao thế? Vì đức Phật nói những vi trần chính chẳng phải những vi trần, đó tạm gọi là những vi trần."],["p","“Bạch đức Thế tôn! Cõi tam thiên, đại thiên của đức Như Lai nói, chính chẳng phải thế giới, đó gọi là thế giới. Bởi vì sao? Vì nếu thế giới là thiệt có ấy, thời là một hợp tướng."],["p","“Đức Như Lai nói một hợp tướng chính chẳng phải một hợp tướng, đó tạm gọi là một hợp tướng.”"],["p","“Nầy Tu Bồ Đề! Một hợp tướng đó bèn là chẳng thể nói được, chỉ nơi kẻ phàm phu tham trước việc ấy thôi."],["p","“Nầy Tu Bồ Đề! Như có người nói:"],["p","Đức Phật nói ngã kiến, nhân kiến, chúng sanh kiến, thọ giả kiến. Nơi ý của ông nghĩ thế nào? Người ấy hiểu nghĩa lý của Phật nói chăng?”"],["p","“Bạch đức Thế Tôn! Không. Người ấy không hiểu nghĩa lý của đức Phật nói. Bởi vì sao? Đức Thế tôn nói ngã kiến, nhân kiến, chúng sanh kiến, thọ giả kiến, chính chẳng phải ngã kiến, nhân kiến, chúng sanh kiến, thọ giả kiến, đó tạm gọi là ngã kiến, nhân kiến, chúng sanh kiến, thọ giả kiến.”"],["p","“Nầy Tu Bồ Đề! Nơi tất cả pháp, người phát tâm Vô thượng Chánh đẳng Chánh giác phải biết như thế, thấy như thế, tin hiểu như thế, chẳng sanh pháp tướng."],["p","“Nầy Tu Bồ Đề! Pháp tướng nói ra đó, đức Như Lai nói chính là không phải pháp tướng, đó tạm gọi là pháp tướng."],["p","“Nầy Tu Bồ Đề! Như có người đem bảy thứ báu đầy cả vô lượng vô số cõi nước để làm việc bố thí. Như có trang thiện nam, người thiện nữ nào, phát tâm Bồ đề, thọ trì kinh nầy, nhẫn đến một bài kệ bốn câu v.v... tự mình thọ trì, đọc tụng, lại giảng cho kẻ khác nghe, thời phước đức của người nầy hơn người trước."],["p","“Giảng nói cho người khác nghe như thế nào? ‘Không chấp lấy nơi tướng, như như chẳng động?’"],["v",["“Bởi vì sao?","“Tất cả những pháp hữu vi,","“Khác nào mộng, huyễn, khác gì"]],["v",["điện, sương, “Như bóng nước, như ảnh tượng,","“Xét suy như thế cho thường chớ","quên!”"]],["p","Đức Phật nói kinh nầy xong, ông Trưởng Lão Tu Bồ Đề cùng với các vị Tỳ kheo, Tỳ kheo ni, Ưu Bà Tắc, Ưu Bà Di, tất cả Trời, Người, A Tu La v.v... trong thế gian, nghe những lời của Đức Phật dạy, thảy đều rất vui mừng, tin nhận, vâng theo tu hành."],["p","Nam mô Bát Nhã Hội Thượng Phật Bồ Tát"],["p","Ma Ha Tát. (3 lần)"]]},{"t":"Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh","b":[["p","Quán Tự Tại Bồ Tát hành thâm Bát Nhã Ba La Mật Đa thời, chiếu kiến ngũ uẩn giai không độ nhứt thiết khổ ách."],["p","Xá Lợi Tử! Sắc bất dị không, không bất dị sắc, sắc tức thị không, không tức thị sắc, thọ, tưởng, hành, thức diệc phục như thị."],["p","Xá Lợi Tử! Thị chư pháp không tướng, bất sanh, bất diệt, bất cấu, bất tịnh, bất tăng, bất giảm. Thị cố không trung vô sắc, vô thọ, tưởng, hành, thức, vô nhãn, nhĩ, tỷ, thiệt, thân, ý, vô sắc, thinh, hương, vị, xúc, pháp, vô nhãn giới, nãi chí vô ý thức giới, vô vô minh diệc vô vô minh tận, nãi chí vô lão tử diệc, vô lão tử tận, vô khổ, tập, diệt, đạo, vô trí diệc vô đắc. Dĩ vô sở đắc cố, Bồ đề tát đỏa y Bát Nhã Ba La Mật Đa cố, tâm vô quái ngại, vô quái ngại cố, vô hữu khủng bố, viễn ly điên đảo mộng tưởng cứu cánh Niết Bàn. Tam thế chư Phật y Bát Nhã Ba La Mật Đa cố, đắc a nậu đa la tam miệu tam bồ đề. Cố tri Bát Nhã Ba La Mật Đa, thị đại thần chú, thị đại minh chú, thị vô thượng chú, thị vô đẳng đẳng chú, năng trừ nhứt thiết khổ, chơn thật bất hư."],["v",["Cố thuyết Bát Nhã Ba La Mật Đa chú.","Tức thuyết chú viết:"]],["p","“Yết đế yết đế, ba la yết đế, ba la tăng yết đế, bồ đề tát bà ha.” (3 lần)"],["p","VÃNG SANH QUYẾT ĐỊNH CHÂN NGÔN"],["p","Nam mô a di đa bà dạ, đa tha già đa dạ, đa địa dạ tha. A di rị đô bà tỳ, a di rị đa tất đam bà tỳ, a di rị đa tỳ ca lan đế, a di rị đa tỳ ca lan đa, dà di nị dà dà na, chỉ đa ca lệ ta bà ha. (3 lần)"],["v",["KIM CANG CHÂN NGÔN","Án, hô rô, hô rô, xả duệ, mục khế, tá ha. (7 lần)","PHỔ HỒI HƯỚNG CHÂN NGÔN"]],["p","Án, ta ma ra, ta ma ra, di ma nẵng tát cáp ra, ma ha thính cáp ra hồng. (3 lần)"],["p","Nhứt hồi hướng: Chân như thiệt tế tâm tâm khế hiệp."],["p","Nhị hồi hướng: Vô thượng Phật quả, bồ đề niệm niệm viên mãn."],["p","Tam hồi hướng: Pháp giới nhứt thiết chúng sanh đồng sanh Tịnh Độ."],["h","Tán Viết"],["v",["Kim cang công đức","Diệu lý nan lương","Như Lai vị chúng quảng tuyên dương","Thọ thí ngộ chân thường","Dĩ chư hoa hương","Phổ tán Pháp Trung Vương.","Nam mô Kỳ Viên Hội Thượng Phật Bồ Tát"]],["p","Ma Ha Tát. (3 lần)"]]},{"t":"Tán Phật","b":[["v",["A Di Đà Phật thân kim sắc","Tướng hảo quang minh vô đẳng luân","Bạch hào uyển chuyển ngũ tu di","Cám mục trừng thanh tứ đại hải","Quang trung hóa Phật vô số ức","Hóa Bồ Tát chúng diệc vô biên","Tứ thập bát nguyện độ chúng sanh","Cửu phẩm hàm linh đăng bỉ ngạn."]],["p","Nam mô Tây Phương Cực Lạc Thế Giới Đại Từ Đại Bi A Di Đà Phật."],["p","Nam mô A Di Đà Phật. (21 lần)"],["p","Nam mô Đại Bi Quán Thế Âm Bồ Tát. (3 lần) Nam mô Đại Thế Chí Bồ Tát. (3 lần)"],["v",["Nam mô Địa Tạng Vương Bồ Tát. (3 lần)","Nam mô Thanh Tịnh Đại Hải Chúng Bồ","Tát. (3 lần)"]]]},{"t":"Phúng Kinh","b":[["v",["Phúng kinh công đức thù thắng hạnh,","Vô biên thắng phước giai hồi hướng,","Phổ nguyện pháp giới chư chúng sanh,","Tốc vãng vô lượng quang Phật sát."]],["v",["Nguyện tiêu tam chướng trừ phiền não,","Nguyện đắc trí huệ chơn minh liễu,","Phổ nguyện tội chướng tất tiêu trừ,","Thế thế thường hành Bồ tát đạo."]],["v",["Nguyện sanh Tây Phương Tịnh Độ trung,","Cửu phẩm Liên hoa vi phụ mẫu,","Hoa khai kiến Phật ngộ vô sanh,","Bất thối Bồ tát vi bạn lữ."]],["v",["Nguyện dĩ thử công đức,","Phổ cập ư nhứt thiết,","Ngã đẳng dữ chúng sanh,","Giai cộng thành Phật đạo."]]]},{"t":"Tam Quy Y","b":[["p","Tự quy y Phật, đương nguyện chúng sanh, thể giai đại đạo, phát vô thượng tâm. (1 lạy)"],["p","Tự quy y Pháp, đương nguyện chúng sanh, thâm nhập kinh tạng, trí huệ như hải. (1 lạy)"],["p","Tự quy y Tăng, đương nguyện chúng sanh, thống lý đại chúng, nhất thiết vô ngại. (1 lạy)"]]},{"t":"Hồi Hướng","b":[["v",["Nguyện đem công đức nầy","Hướng về khắp tất cả","Đệ tử và chúng sanh","Đều trọn thành phật đạo."]]]},{"t":"Cúng Hương Tán Phật","b":[["v",["Nguyện thử diệu hương vân","Biến mãn thập phương giới","Cúng dường nhất thiết Phật","Tôn Pháp, chư Bồ Tát","Vô biên Thanh văn chúng","Cập nhất thiết thánh hiền","Duyên khởi quang minh đài","Xứng tánh tác Phật sự","Phổ huân chư chúng sanh","Giai phát Bồ Đề tâm","Viễn ly chư vọng nghiệp","Viên thành vô thượng đạo."]]],"p":"Phần Dịch Âm"},{"t":"Kỳ Nguyện","b":[["p","Tư thời đệ tử chúng đẳng phúng tụng Đại thừa kinh chú, xưng tán hồng danh, tập thử công đức, nguyện thập phương thường trú Tam bảo, Bổn sư Thích Ca Mâu Ni Phật, từ bi gia hộ đệ tử... .... Pháp danh...\u0001... phiền não đoạn diệt, nghiệp chướng tiêu trừ, thường hoạch kiết tường, vĩnh ly khổ ách. Phổ nguyện âm siêu dương thới, hải yến hà thanh, pháp giới chúng sanh tề thành Phật đạo."]],"p":"Phần Dịch Âm"},{"t":"Tán Phật","b":[["v",["Pháp vương vô thượng tôn","Tam giới vô luân thất","Thiên nhân chi Đạo sư","Tứ sanh chi từ phụ","Ư nhất niệm quy y","Năng diệt tam kỳ nghiệp","Xưng dương nhược tán thán","Ức kiếp mạc năng tận."]]],"p":"Phần Dịch Âm"},{"t":"Quán Tưởng","b":[["v",["Năng lễ sở lễ tánh không tịch","Cảm ứng đạo giao nan tư nghì","Ngã thử đạo tràng như đế châu","Thập phương chư Phật ảnh hiện trung","Ngã thân ảnh hiện chư Phật tiền","Đầu diện tiếp túc quy mạng lễ."]]],"p":"Phần Dịch Âm"},{"t":"Chí Tâm Đảnh Lễ","b":[["p","Chí tâm đảnh lễ: Nam mô tận hư không biến pháp giới quá, hiện, vị lai thập phương chư Phật, Tôn pháp, Hiền thánh tăng thường trú Tam Bảo. (1 lạy)"],["p","Chí tâm đảnh lễ: Nam mô Ta Bà Giáo Chủ Bổn Sư Thích Ca Mâu Ni Phật, Đương Lai Hạ Sanh Di Lặc Tôn Phật, Đại Trí Văn Thù Sư Lợi Bồ Tát, Đại Hạnh Phổ Hiền Bồ Tát, Hộ Pháp Chư Tôn Bồ Tát, Linh Sơn Hội Thượng Phật Bồ Tát. (1 lạy)"],["p","Chí tâm đảnh lễ: Nam mô Tây Phương Cực Lạc Thế Giới Đại Từ Đại Bi A Di Đà Phật, Đại Bi Quán Thế Âm Bồ Tát, Đại Thế Chí Bồ Tát, Đại Nguyện Địa Tạng Vương Bồ Tát, Thanh Tịnh Đại Hải Chúng Bồ Tát. (1 lạy)"]],"p":"Phần Dịch Âm"},{"t":"Hương Tán","b":[["v",["Lư hương xạ nhiệt,","Pháp giới mông huân,","Chư Phật hải hội tất diêu văn,","Tùy xứ kiết tường vân,","Thành ý phương ân,","Chư Phật hiện toàn thân."]],["v",["Nam mô Hương Vân Cái Bồ Tát. (3 lần)","TỊNH KHẨU NGHIỆP CHÂN NGÔN","Tu rị, tu rị, ma ha tu rị, tu tu rị, ta bà ha. (3 lần)","TỊNH TAM NGHIỆP CHÂN NGÔN"]],["v",["Án ta phạ, bà phạ, thuật đà ta phạ,","đạt ma ta phạ, bà phạ thuật độ hám. (3 lần)"]],["p","AN THỔ ĐỊA CHÂN NGÔN"],["p","Nam mô tam mãn đa một đà nẫm. Án độ rô độ rô, địa vĩ ta bà ha. (3 lần)"],["p","PHỔ CÚNG DƯỜNG CHÂN NGÔN"],["v",["Án nga nga nẵng, tam bà phạ, phiệt","nhật ra hồng. (3 lần)"]],["h","Phụng Thỉnh Bát Kim Cang"],["v",["Phụng thỉnh Thanh Trừ Tai Kim Cang.","Phụng thỉnh Bích Độc Thần Kim Cang.","Phụng thỉnh Huỳnh Tùy Cầu Kim Cang.","Phụng thỉnh Bạch Tịnh Thủy Kim Cang.","Phụng thỉnh Xích Thanh Hỏa Kim Cang.","Phụng thỉnh Định Trì Tai Kim Cang.","Phụng thỉnh Tử Hiền Kim Cang.","Phụng thỉnh Đại Thần Kim Cang."]],["h","Phụng Thỉnh Tứ Bồ Tát"],["v",["Phụng thỉnh Kim Cang Quyến Bồ tát.","Phụng thỉnh Kim Cang Sách Bồ tát.","Phụng thỉnh Kim Cang Ái Bồ tát.","Phụng thỉnh Kim Cang Ngữ Bồ tát."]]],"p":"Phần Dịch Âm"},{"t":"Phát Nguyện Văn","b":[["v",["Khể thủ tam giới tôn","Quy mạng thập phương Phật","Ngã kim phát hoằng nguyện","Trì thử Kim Cang kinh","Thượng báo tứ trọng ân","Hạ tế tam đồ khổ","Nhược hữu kiến, văn giả","Tất phát Bồ Đề tâm","Tận thử nhất báo thân","Đồng sanh Cực Lạc quốc."]],["h","Vân Hà Phạm"],["v",["Vân hà đắc trường thọ","Kim cang bất hoại thân","Phục dĩ hà nhân duyên","Đắc đại kiên cố lực","Vân hà ư thử kinh","Cứu cánh đáo bỉ ngạn","Nguyện Phật khai vi mật","Quảng vị chúng sanh thuyết."]],["p","Nam mô Bổn Sư Thích Ca Mâu Ni Phật. (3 lần)"]],"p":"Phần Dịch Âm"},{"t":"Khai Kinh Kệ","b":[["v",["Vô thượng thậm thâm vi diệu pháp","Bá thiên vạn kiếp nan tao ngộ","Ngã kim kiến văn đắc thọ trì","Nguyện giải Như Lai chân thật nghĩa."]],["p","Nam mô Bát Nhã Hội Thượng Phật Bồ Tát"],["p","Ma Ha Tát. (3 lần)"]],"p":"Phần Dịch Âm"},{"t":"Phật Thuyết Kim Cang Bát Nhã Ba La Mật Kinh","b":[["p","(Đời Diêu Tần, Ngài Tam Tạng Pháp Sư"],["p","Cưu Ma la Thập vâng chiếu dịch.)"],["p","Như thị ngã văn. Nhất thời Phật tại Xá-vệ quốc, Kỳ Thọ Cấp Cô Độc viên, dữ đại tỳ-kheo chúng thiên nhị bá ngũ thập nhân câu."],["p","Nhĩ thời Thế Tôn thực thời, trước y trì bát nhập Xá-vệ đại thành khất thực. Ư kỳ thành trung thứ đệ khất dĩ, hoàn đáo bản xứ, phạn thực ngật, thâu y bát, tẩy túc dĩ, phu tòa nhi tọa."],["p","Thời Trưởng lão Tu-bồ-đề tại đại chúng trung tức tùng tòa khởi, thiên đản hữu kiên, hữu tất trước địa, hiệp chưởng cung kính nhi bạch Phật ngôn: “Hy hữu Thế Tôn! Như Lai thiện hộ niệm chư Bồ Tát, thiện phó chúc chư Bồ Tát."],["p","“Thế Tôn! Thiện nam tử, thiện nữ nhân phát A-nậu-đa-la Tam-miệu Tam-bồ-đề tâm, ưng vân hà trụ, vân hà hàng phục kỳ tâm?”"],["p","Phật ngôn: “Thiện tai! Thiện tai!"],["p","Tu-bồ-đề, như nhữ sở thuyết. Như Lai thiện hộ niệm chư Bồ Tát, thiện phó chúc chư Bồ Tát. Nhữ kim đế thính, đương vị nhữ thuyết. Thiện nam tử, thiện nữ nhân phát A-nậu-đa-la Tam-miệu Tam-bồ-đề tâm, ưng như thị trụ, như thị hàng phục kỳ tâm.”"],["p","“Duy nhiên Thế Tôn. Nguyện nhạo dục văn.”"],["p","Phật cáo Tu-bồ-đề: “Chư Bồ Tát ma-ha-tát ưng như thị hàng phục kỳ tâm:"],["p","Sở hữu nhất thiết chúng sanh chi loại, nhược nỗn sanh, nhược thai sanh, nhược thấp sanh, nhược hóa sanh, nhược hữu sắc, nhược vô sắc, nhược hữu tưởng, nhược vô tưởng, nhược phi hữu tưởng phi vô tưởng, ngã giai linh nhập Vô dư Niết-bàn nhi diệt độ chi. Như thị diệt độ vô lượng vô số vôâ biên chúng sanh, thật vô chúng sanh đắc diệt độ giả."],["p","“Hà dĩ cố? Tu-bồ-đề, nhược Bồ Tát hữu ngã tướng, nhân tướng, chúng sanh tướng, thọ giả tướng, tức phi Bồ Tát."],["p","“Phục thứ Tu-bồ-đề, Bồ Tát ư pháp ưng vô sở trụ hành ư bố thí. Sở vị, bất trụ sắc bố thí, bất trụ thanh, hương, vị, xúc, pháp bố thí."],["p","“Tu-bồ-đề, Bồ Tát ưng như thị bố thí, bất trụ ư tướng."],["p","“Hà dĩ cố? Nhược Bồ Tát bất trụ tướng bố thí, kỳ phước đức bất khả tư lương."],["p","“Tu-bồ-đề, ư ý vân hà? Đông phương hư không khả tư lương phủ?”"],["p","“Phất dã, Thế Tôn.”"],["p","“Tu-bồ-đề, nam, tây, bắc phương, tứ duy, thượng, hạ hư không khả tư lương phủ?”"],["p","“Phất dã, Thế Tôn.”"],["p","“Tu-bồ-đề! Bồ Tát vô trụ tướng bố thí phước đức, diệc phục như thị, bất khả tư lương. Tu-bồ-đề, Bồ Tát đản ưng như sở giáo trụ."],["p","“Tu-bồ-đề, ư ý vân hà? Khả dĩ thân tướng kiến Như Lai phủ?”"],["p","“Phất dã, Thế Tôn. Bất khả dĩ thân tướng đắc kiến Như Lai. Hà dĩ cố? Như Lai sở thuyết thân tướng tức phi thân tướng.”"],["p","Phật cáo Tu-bồ-đề: “Phàm sở hữu tướng giai thị hư vọng. Nhược kiến chư tướng phi tướng tắc kiến Như Lai.”"],["p","Tu-bồ-đề bạch Phật ngôn: “Thế Tôn, phả hữu chúng sanh đắc văn như thị ngôn thuyết chương cú sanh thật tín phủ?”"],["p","Phật cáo Tu-bồ-đề: “Mạc tác thị thuyết. Như Lai diệt hậu, hậu ngũ bá tuế, hữu trì giới tu phước giả, ư thử chương cú năng sanh tín tâm, dĩ thử vi thật. Đương tri thị nhân bất ư nhất Phật, nhị Phật, tam tứ ngũ Phật nhi chủng thiện căn. Dĩ ư vô lượng thiên vạn Phật sở chủng chư thiện căn. Văn thị chương cú, nãi chí nhất niệm sanh tịnh tín giả. Tu-bồ-đề, Như Lai tất tri, tất kiến thị chư chúng sanh đắc như thị vô lượng phước đức."],["p","“Hà dĩ cố? Thị chư chúng sanh vô phục ngã tướng, nhân tướng, chúng sanh tướng, thọ giả tướng, vô pháp tướng diệc vô phi pháp tướng."],["p","“Hà dĩ cố? Thị chư chúng sanh nhược tâm thủ tướng tắc vi trước ngã, nhân, chúng sanh, thọ giả. Hà dĩ cố?"],["p","Nhược thủ pháp tướng, tức trước ngã, nhân, chúng sanh, thọ giả. Nhược thủ phi pháp tướng, tức trước ngã, nhân, chúng sanh, thọ giả. Thị cố bất ưng thủ pháp, bất ưng thủ phi pháp."],["p","“Dĩ thị nghĩa cố, Như Lai thường thuyết, nhữ đẳng tỳ-kheo tri ngã thuyết pháp như phiệt dụ giả, pháp thượng ưng xả, hà huống phi pháp?"],["p","“Tu-bồ-đề, ư ý vân hà? Như Lai đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề da?"],["p","Như Lai hữu sở thuyết pháp da?”"],["p","Tu-bồ-đề ngôn: “Như ngã giải Phật sở thuyết nghĩa, vô hữu định pháp danh A-nậu-đa-la Tam-miệu Tam-bồ-đề, diệc vô hữu định pháp Như Lai khả thuyết. Hà dĩ cố? Như Lai sở thuyết pháp giai bất khả thủ, bất khả thuyết, phi pháp, phi phi pháp. Sở dĩ giả hà? Nhất thiết hiền thánh giai dĩ vô vi pháp, nhi hữu sai biệt.”"],["p","“Tu-bồ-đề, ư ý vân hà? Nhược nhân mãn tam thiên đại thiên thế giới thất bảo dĩ dụng bố thí. Thị nhân sở đắc phước đức ninh vi đa phủ?”"],["p","Tu-bồ-đề ngôn: “Thậm đa, Thế Tôn."],["p","Hà dĩ cố? Thị phước đức tức phi phước đức tánh, thị cố Như Lai thuyết phước đức đa.”"],["p","“Nhược phục hữu nhân ư thị kinh trung thọ trì, nãi chí tứ cú kệ đẳng, vị tha nhân thuyết, kỳ phước thắng bỉ."],["p","“Hà dĩ cố? Tu-bồ-đề, nhất thiết chư Phật cập chư Phật A-nậu-đa-la Tam-miệu Tam-bồ-đề pháp giai tùng thử kinh xuất."],["p","“Tu-bồ-đề, sở vị Phật pháp giả tức phi Phật pháp."],["p","“Tu-bồ-đề, ư ý vân hà? Tu-đà-hoàn năng tác thị niệm: Ngã đắc Tu-đà-hoàn quả phủ?”"],["p","Tu-bồ-đề ngôn: “Phất dã, Thế Tôn."],["p","Hà dĩ cố? Tu-đà-hoàn danh vi nhập lưu, nhi vô sở nhập. Bất nhập sắc, thanh, hương, vị, xúc, pháp. Thị danh Tu-đà-hoàn.”"],["p","“Tu-bồ-đề, ư ý vân hà? Tư-đà-hàm năng tác thị niệm: Ngã đắc Tư-đà-hàm quả phủ?”"],["p","Tu-bồ-đề ngôn: “Phất dã, Thế Tôn."],["p","Hà dĩ cố? Tư-đà-hàm danh nhất vãng lai, nhi thật vô vãng lai. Thị danh Tư-đà-hàm.”"],["p","“Tu-bồ-đề, ư ý vân hà? A-na-hàm năng tác thị niệm: Ngã đắc A-na-hàm quả phủ?”"],["p","Tu-bồ-đề ngôn: “Phất dã, Thế Tôn."],["p","Hà dĩ cố? A-na-hàm danh vi bất lai, nhi thật vô lai. Thị cố danh A-na-hàm.”"],["p","“Tu-bồ-đề, ư ý vân hà? A-la-hán năng tác thị niệm: Ngã đắc A-la-hán đạo phủ?”"],["p","Tu-bồ-đề ngôn: “Phất dã, Thế Tôn."],["p","Hà dĩ cố? Thật vô hữu pháp danh A-la-hán. Thế Tôn, nhược A-la-hán tác thị niệm: Ngã đắc A-la-hán đạo. Tức vi trước ngã, nhân, chúng sanh, thọ giả."],["p","“Thế Tôn, Phật thuyết ngã đắc Vô tránh Tam-muội, nhân trung tối vi đệ nhất, thị đệ nhất ly dục A-la-hán. Ngã bất tác thị niệm: Ngã thị ly dục A-la-hán."],["p","“Thế Tôn, ngã nhược tác thị niệm:"],["p","Ngã đắc A-la-hán đạo, Thế Tôn tắc bất thuyết: Tu-bồ-đề thị nhạo A-lan-na hạnh giả. Dĩ Tu-bồ-đề thật vô sở hành, nhi danh Tu-bồ-đề thị nhạo A-lan-na hạnh.”"],["p","Phật cáo Tu-bồ-đề: “Ư ý vân hà? Như Lai tích tại Nhiên Đăng Phật sở, ư pháp hữu sở đắc phủ?”"],["p","“Thế Tôn, Như Lai tại Nhiên Đăng Phật sở, ư pháp thật vô sở đắc.”"],["p","“Tu-bồ-đề, ư ý vân hà? Bồ Tát trang nghiêm Phật độ phủ?”"],["p","“Phất dã, Thế Tôn. Hà dĩ cố? Trang nghiêm Phật độ giả tức phi trang nghiêm, thị danh trang nghiêm.”"],["p","“Thị cố Tu-bồ-đề, chư Bồ Tát ma-ha-tát ưng như thị sanh thanh tịnh tâm: Bất ưng trụ sắc sanh tâm, bất ưng trụ thanh, hương, vị, xúc, pháp sanh tâm."],["p","Ưng vô sở trụ nhi sanh kỳ tâm.”"],["p","“Tu-bồ-đề, thí như hữu nhân, thân như Tu-di sơn vương. Ư ý vân hà, thị thân vi đại phủ?”"],["p","Tu-bồ-đề ngôn: “Thậm đại, Thế Tôn."],["p","Hà dĩ cố? Phật thuyết phi thân thị danh đại thân."],["p","“Tu-bồ-đề, như Hằng hà trung sở hữu sa số, như thị sa đẳng Hằng hà. Ư ý vân hà, thị chư Hằng hà sa đẳng ninh vi đa phủ?”"],["p","Tu-bồ-đề ngôn: “Thậm đa, Thế Tôn."],["p","Đản chư Hằng hà thượng đa vô số, hà huống kỳ sa.”"],["p","“Tu-bồ-đề! Ngã kim thật ngôn cáo nhữ. Nhược hữu thiện nam tử, thiện nữ nhân dĩ thất bảo mãn sở Hằng hà sa số tam thiên đại thiên thế giới, dĩ dụng bố thí đắc phước đa phủ?”"],["p","Tu-bồ-đề ngôn: “Thậm đa, Thế Tôn.”"],["p","Phật cáo Tu-bồ-đề: “Nhược thiện nam tử, thiện nữ nhân ư thử kinh trung nãi chí thọ trì tứ cú kệ đẳng, vị tha nhân thuyết, nhi thử phước đức thắng tiền phước đức."],["p","“Phục thứ Tu-bồ-đề, tùy thuyết thị kinh, nãi chí tứ cú kệ đẳng, đương tri thử xứ nhất thiết thế gian thiên, nhân, a-tu-la giai ưng cúng dường như Phật tháp miếu. Hà huống hữu nhân tận năng thọ trì độc tụng."],["p","“Tu-bồ-đề, đương tri thị nhân thành tựu tối thượng đệ nhất hy hữu chi pháp."],["p","Nhược thị kinh điển sở tại chi xứ, tắc vi hữu Phật nhược tôn trọng đệ tử.”"],["p","Nhĩ thời Tu-bồ-đề bạch Phật ngôn: “Thế Tôn! Đương hà danh thử kinh? Ngã đẳng vân hà phụng trì?”"],["p","Phật cáo Tu-bồ-đề: “Thị kinh danh vi Kim cang Bát-nhã Ba-la-mật. Dĩ thị danh tự nhữ đương phụng trì. Sở dĩ giả hà? Tu-bồ-đề, Phật thuyết Bát-nhã ba-la-mật tức phi Bát-nhã ba-la-mật."],["p","“Tu-bồ-đề, ư ý vân hà? Như Lai hữu sở thuyết pháp phủ?”"],["p","Tu-bồ-đề bạch Phật ngôn: “Thế Tôn, Như Lai vô sở thuyết.”"],["p","“Tu-bồ-đề, ư ý vân hà? Tam thiên đại thiên thế giới sở hữu vi trần thị vi đa phủ?”"],["p","Tu-bồ-đề ngôn: “Thậm đa, Thế Tôn.”"],["p","“Tu-bồ-đề, chư vi trần Như Lai thuyết phi vi trần, thị danh vi trần. Như Lai thuyết thế giới phi thế giới, thị danh thế giới."],["p","“Tu-bồ-đề, ư ý vân hà? Khả dĩ tam thập nhị tướng kiến Như Lai phủ?”"],["p","“Phất dã, Thế Tôn. Bất khả dĩ tam thập nhị tướng đắc kiến Như Lai. Hà dĩ cố? Như Lai thuyết tam thập nhị tướng tức thị phi tướng, thị danh tam thập nhị tướng.”"],["p","“Tu-bồ-đề, nhược hữu thiện nam tử, thiện nữ nhân dĩ Hằng hà sa đẳng thân mạng bố thí. Nhược phục hữu nhân ư thử kinh trung nãi chí thọ trì tứ cú kệ đẳng, vị tha nhân thuyết, kỳ phước thậm đa.”"],["p","Nhĩ thời Tu-bồ-đề văn thuyết thị kinh, thâm giải nghĩa thú, thế lệ bi khấp nhi bạch Phật ngôn: “Hy hữu Thế Tôn, Phật thuyết như thị thậm thâm kinh điển. Ngã tùng tích lai sở đắc huệ nhãn, vị tằng đắc văn như thị chi kinh."],["p","“Thế Tôn, nhược phục hữu nhân đắc văn thị kinh, tín tâm thanh tịnh tắc sanh thật tướng. Đương tri thị nhân thành tựu đệ nhất hy hữu công đức."],["p","“Thế Tôn! Thị thật tướng giả tức thị phi tướng, thị cố Như Lai thuyết danh thật tướng."],["p","“Thế Tôn! Ngã kim đắc văn như thị kinh điển, tín giải thọ trì bất túc vi nan."],["p","Nhược đương lai thế hậu ngũ bá tuế, kỳ hữu chúng sanh đắc văn thị kinh tín giải thọ trì. Thị nhân tắc vi đệ nhất hy hữu."],["p","Hà dĩ cố? Thử nhân vô ngã tướng, nhân tướng, chúng sanh tướng, thọ giả tướng."],["p","Sở dĩ giã hà? Ngã tướng tức thị phi tướng."],["p","Nhân tướng, chúng sanh tướng, thọ giả tướng tức thị phi tướng. Hà dĩ cố? Ly nhất thiết chư tướng tức danh chư Phật.”"],["p","Phật cáo Tu-bồ-đề: “Như thị, như thị. Nhược phục hữu nhân đắc văn thị kinh, bất kinh, bất bố, bất úy, đương tri thị nhân thậm vi hy hữu."],["p","“Hà dĩ cố? Tu-bồ-đề, Như Lai thuyết đệ nhất ba-la-mật phi đệ nhất ba-la-mật, thị danh đệ nhất ba-la-mật."],["p","“Tu-bồ-đề! Nhẫn nhục ba-la-mật Như Lai thuyết phi Nhẫn nhục ba-la-mật."],["p","Hà dĩ cố? Như ngã tích vị Ca-lỵ vương cát triệt thân thể. Ngã ư nhĩ thời vô ngã tướng, vô nhân tướng, vô chúng sanh tướng, vô thọ giả tướng."],["p","“Hà dĩ cố? Ngã ư vãng tích tiết tiết chi giải thời, nhược hữu ngã tướng, nhân tướng, chúng sanh tướng, thọ giả tướng, ưng sanh sân hận."],["p","“Tu-bồ-đề, hựu niệm quá khứ ư ngũ bá thế tác nhẫn nhục tiên nhân. Ư nhĩ sở thế vô ngã tướng, vô nhân tướng, vô chúng sanh tướng, vô thọ giả tướng."],["p","“Thị cố Tu-bồ-đề, Bồ Tát ưng ly nhất thiết tướng phát A-nậu-đa-la Tam-miệu Tam-bồ-đề tâm."],["p","“Bất ưng trụ sắc sanh tâm, bất ưng trụ thanh, hương, vị, xúc, pháp sanh tâm."],["v",["Ưng sanh vô sở trụ tâm.","“Nhược tâm hữu trụ tắc vi phi trụ.","“Thị cố Phật thuyết Bồ Tát tâm bất ưng trụ sắc bố thí."]],["p","“Tu-bồ-đề! Bồ Tát vị lợi ích nhất thiết chúng sanh, ưng như thị bố thí."],["p","“Như Lai thuyết nhất thiết chư tướng tức thị phi tướng, hựu thuyết nhất thiết chúng sanh tức phi chúng sanh."],["p","“Tu-bồ-đề! Như Lai thị chân ngữ giả, thật ngữ giả, như ngữ giả, bất cuống ngữ giả, bất dị ngữ giả."],["p","“Tu-bồ-đề! Như Lai sở đắc pháp. Thử pháp vô thật vô hư."],["p","“Tu-bồ-đề, nhược Bồ Tát tâm trụ ư pháp nhi hành bố thí, như nhân nhập ám, tắc vô sở kiến."],["p","“Nhược Bồ Tát tâm bất trụ pháp nhi hành bố thí, như nhân hữu mục, nhật quang minh chiếu kiến chủng chủng sắc."],["p","“Tu-bồ-đề, đương lai chi thế nhược hữu thiện nam tử, thiện nữ nhân năng ư thử kinh thọ trì độc tụng, tắc vi Như Lai dĩ Phật trí huệ tất tri thị nhân, tất kiến thị nhân, giai đắc thành tựu vô lượng vô biên công đức."],["p","“Tu-bồ-đề, nhược hữu thiện nam tử, thiện nữ nhân sơ nhật phần dĩ Hằng hà sa đẳng thân bố thí, trung nhật phần phục dĩ Hằng hà sa đẳng thân bố thí, hậu nhật phần diệc dĩ Hằng hà sa đẳng thân bố thí. Như thị vô lượng bá thiên vạn ức kiếp dĩ thân bố thí."],["p","“Nhược phục hữu nhân văn thử kinh điển tín tâm bất nghịch, kỳ phước thắng bỉ. Hà huống thơ tả, thọ trì, độc tụng, vị nhân giải thuyết."],["p","“Tu-bồ-đề, dĩ yếu ngôn chi, thị kinh hữu bất khả tư nghị, bất khả xưng lượng, vô biên công đức."],["p","“Như Lai vị phát Đại thừa giả thuyết, vị phát Tối thượng thừa giả thuyết."],["p","Nhược hữu nhân năng thọ trì độc tụng, quảng vị nhân thuyết, Như Lai tất tri thị nhân, tất kiến thị nhân giai đắc thành tựu bất khả lượng, bất khả xứng, vô hữu biên, bất khả tư nghị công đức."],["p","“Như thị nhân đẳng tắc vi hà đảm Như Lai A-nậu-đa-la Tam-miệu Tam-bồ-đề."],["p","“Hà dĩ cố? Tu-bồ-đề, nhược nhạo tiểu pháp giả, trước ngã kiến, nhân kiến, chúng sanh kiến, thọ giả kiến, tắc ư thử kinh bất năng thính thọ, độc tụng, vị nhân giải thuyết."],["p","“Tu-bồ-đề, tại tại xứ xứ nhược hữu thử kinh, nhất thiết thế gian thiên, nhân, a-tu-la sở ưng cúng dường. Đương tri thử xứ tắc vi thị tháp, giai ưng cung kính tác lễ vi nhiễu, dĩ chư hoa hương nhi tán kỳ xứ."],["p","“Phục thứ Tu-bồ-đề! Thiện nam tử, thiện nữ nhân thọ trì độc tụng thử kinh, nhược vi nhân khinh tiện. Thị nhân tiên thế tội nghiệp ưng đọa ác đạo, dĩ kim thế nhân khinh tiện cố, tiên thế tội nghiệp tắc vi tiêu diệt, đương đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề."],["p","“Tu-bồ-đề, ngã niệm quá khứ vô lượng a-tăng-kỳ kiếp, ư Nhiên Đăng Phật tiền đắc trị bát bá tứ thiên vạn ức na-do-tha chư Phật, tất giai cúng dường thừa sự vô không quá giả. Nhược phục hữu nhân ư hậu mạt thế, năng thọ trì độc tụng thử kinh, sở đắc công đức, ư ngã sở cúng dường chư Phật công đức, bá phần bất cập nhất, thiên vạn ức phần, nãi chí toán số thí dụ sở bất năng cập."],["p","“Tu-bồ-đề, nhược thiện nam tử, thiện nữ nhân ư hậu mạt thế hữu thọ trì độc tụng thử kinh sở đắc công đức, ngã nhược cụ thuyết giả, hoặc hữu nhân văn tâm tắc cuồng loạn hồ nghi bất tín."],["p","“Tu-bồ-đề, đương tri thị kinh nghĩa bất khả tư nghị, quả báo diệc bất khả tư nghị.”"],["p","Nhĩ thời Tu-bồ-đề bạch Phật ngôn: “Thế Tôn! Thiện nam tử, thiện nữ nhân phát A-nậu-đa-la Tam-miệu Tam-bồ-đề tâm, vân hà ưng trụ? Vân hà hàng phục kỳ tâm?”"],["p","Phật cáo Tu-bồ-đề: “Thiện nam tử, thiện nữ nhân phát A-nậu-đa-la Tam-miệu Tam-bồ-đề giả, đương sanh như thị tâm: Ngã ưng diệt độ nhất thiết chúng sanh. Diệt độ nhất thiết chúng sanh dĩ, nhi vô hữu nhất chúng sanh thật diệt độ giả."],["p","“Hà dĩ cố? Tu-bồ-đề, nhược Bồ Tát hữu ngã tướng, nhân tướng, chúng sanh tướng, thọ giả tướng, tức phi Bồ Tát."],["p","“Sở dĩ giả hà? Tu-bồ-đề, thật vô hữu pháp phát A-nậu-đa-la Tam-miệu Tam-bồ-đề giả."],["p","“Tu-bồ-đề, ư ý vân hà? Như Lai ư Nhiên Đăng Phật sở hữu pháp đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề phủ?”"],["p","“Phất dã, Thế Tôn. Như ngã giải Phật sở thuyết nghĩa, Phật ư Nhiên Đăng Phật sở vô hữu pháp đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề.”"],["p","Phật ngôn: “Như thị, như thị."],["p","Tu-bồ-đề, thật vô hữu pháp Như Lai đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề."],["p","“Tu-bồ-đề, nhược hữu pháp Như Lai đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề giả, Nhiên Đăng Phật tắc bất dữ ngã thọ ký: Nhữ ư lai thế đương đắc tác Phật hiệu Thích-ca Mâu-ni. Dĩ thật vô hữu pháp đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề, thị cố Nhiên Đăng Phật dữ ngã thọ ký, tác thị ngôn: Nhữ ư lai thế đương đắc tác Phật hiệu Thích-ca Mâu-ni."],["p","“Hà dĩ cố? Như Lai giả tức chư pháp như nghĩa."],["p","“Nhược hữu nhân ngôn: Như Lai đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề."],["p","Tu-bồ-đề! Thật vô hữu pháp Phật đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề."],["p","“Tu-bồ-đề! Như Lai sở đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề, ư thị trung vô thật, vô hư."],["p","“Thị cố Như Lai thuyết nhất thiết pháp giai thị Phật pháp."],["p","“Tu-bồ-đề! Sở ngôn nhất thiết pháp giả, tức phi nhất thiết pháp, thị cố danh nhất thiết pháp. Tu-bồ-đề, thí như nhân thân trường đại.”"],["p","Tu-bồ-đề ngôn: “Thế Tôn, Như Lai thuyết nhân thân trường đại tức vi phi đại thân, thị danh đại thân.”"],["p","“Tu-bồ-đề! Bồ Tát diệc như thị."],["p","Nhược tác thị ngôn: Ngã đương diệt độ vô lượng chúng sanh tức bất danh Bồ Tát. Hà dĩ cố? Tu-bồ-đề! Thật vô hữu pháp danh vi Bồ Tát. Thị cố Phật thuyết nhất thiết pháp vô ngã, vô nhân, vô chúng sanh, vô thọ giả."],["p","“Tu-bồ-đề! Nhược Bồ Tát tác thị ngôn: “Ngã đương trang nghiêm Phật độ”, thị bất danh Bồ Tát. Hà dĩ cố? Như Lai thuyết trang nghiêm Phật độ giả, tức phi trang nghiêm thị danh trang nghiêm."],["p","“Tu-bồ-đề! Nhược Bồ Tát thông đạt vô ngã pháp giả, Như Lai thuyết danh chân thị Bồ Tát."],["v",["“Tu-bồ-đề! Ư ý vân hà? Như Lai hữu nhục nhãn phủ?”","“Như thị, Thế Tôn. Như Lai hữu nhục nhãn.”","“Tu-bồ-đề! Ư ý vân hà? Như Lai hữu thiên nhãn phủ?”","“Như thị, Thế Tôn. Như Lai hữu thiên nhãn.”","“Tu-bồ-đề! Ư ý vân hà? Như Lai hữu huệ nhãn phủ?”","“Như thị, Thế Tôn. Như Lai hữu huệ nhãn.”","“Tu-bồ-đề! Ư ý vân hà? Như Lai hữu pháp nhãn phủ?”","“Như thị, Thế Tôn. Như Lai hữu pháp nhãn.”","“Tu-bồ-đề! Ư ý vân hà? Như Lai hữu Phật nhãn phủ?”","“Như thị, Thế Tôn. Như Lai hữu Phật nhãn.”"]],["p","“Tu-bồ-đề! Ư ý vân hà? Hằng hà trung sở hữu sa, Phật thuyết thị sa phủ?”"],["p","“Như thị, Thế Tôn. Như Lai thuyết thị sa.”"],["p","“Tu-bồ-đề! Ư ý vân hà? Như nhất Hằng hà trung sở hữu sa, hữu như thị đẳng Hằng hà, thị chư Hằng hà sở hữu sa số Phật thế giới. Như thị ninh vi đa phủ?”"],["p","“Thậm đa, Thế Tôn.”"],["p","Phật cáo Tu-bồ-đề: “Nhĩ sở quốc độ trung sở hữu chúng sanh nhược can chủng tâm Như Lai tất tri. Hà dĩ cố? Như Lai thuyết chư tâm giai vi phi tâm, thị danh vi tâm."],["p","Sở dĩ giã hà? Tu-bồ-đề! Quá khứ tâm bất khả đắc, hiện tại tâm bất khả đắc, vị lai tâm bất khả đắc."],["p","“Tu-bồ-đề! Ư ý vân hà? Nhược hữu nhân mãn tam thiên đại thiên thế giới thất bảo dĩ dụng bố thí, thị nhân dĩ thị nhân duyên đắc phước đa phủ?”"],["p","“Như thị, Thế Tôn. Thử nhân dĩ thị nhân duyên đắc phước thậm đa.”"],["p","“Tu-bồ-đề! Nhược phước đức hữu thật, Như Lai bất thuyết đắc phước đức đa. Dĩ phước đức vô cố, Như Lai thuyết đắc phước đức đa."],["p","“Tu-bồ-đề! Ư ý vân hà? Phật khả dĩ cụ túc sắc thân kiến phủ?”"],["p","“Phất dã, Thế Tôn. Như Lai bất ưng dĩ cụ túc sắc thân kiến. Hà dĩ cố? Như Lai thuyết cụ túc sắc thân tức phi cụ túc sắc thân, thị danh cụ túc sắc thân."],["p","“Tu-bồ-đề! Ư ý vân hà? Như Lai khả dĩ cụ túc chư tướng kiến phủ?”"],["p","“Phất dã, Thế Tôn. Như Lai bất ưng dĩ cụ túc chư tướng kiến. Hà dĩ cố? Như Lai thuyết chư tướng cụ túc tức phi cụ túc, thị danh chư tướng cụ túc.”"],["p","“Tu-bồ-đề! Nhữ vật vị Như Lai tác thị niệm: Ngã đương hữu sở thuyết pháp."],["p","Mạc tác thị niệm. Hà dĩ cố? Nhược nhân ngôn Như Lai hữu sở thuyết pháp tức vi báng Phật, bất năng giải ngã sở thuyết cố."],["p","“Tu-bồ-đề! Thuyết pháp giả vô pháp khả thuyết, thị danh thuyết pháp.”"],["p","Nhĩ thời Huệ Mạng Tu-bồ-đề bạch Phật ngôn: “Phả hữu chúng sanh ư vị lai thế văn thuyết thị pháp sanh tín tâm phủ?” Phật ngôn: “Tu-bồ-đề! Bỉ phi chúng sanh phi bất chúng sanh."],["p","Hà dĩ cố? Tu-bồ-đề! Chúng sanh, chúng sanh giả, Như Lai thuyết phi chúng sanh thị danh chúng sanh.”"],["p","Tu-bồ-đề bạch Phật ngôn: “Phật đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề, vi vô sở đắc da?”"],["p","Phật ngôn: “Như thị, như thị."],["p","Tu-bồ-đề, ngã ư A-nậu-đa-la Tam-miệu Tam-bồ-đề nãi chí vô hữu thiểu pháp khả đắc, thị danh A-nậu-đa-la Tam-miệu Tam-bồ-đề."],["p","“Phục thứ Tu-bồ-đề! Thị pháp bình đẳng vô hữu cao hạ, thị danh A-nậu-đa-la Tam-miệu Tam-bồ-đề. Dĩ vô ngã, vô nhân, vô chúng sanh, vô thọ giả, tu nhất thiết thiện pháp tức đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề. Tu-bồ-đề! Sở ngôn thiện pháp giả, Như Lai thuyết phi thiện pháp thị danh thiện pháp."],["p","“Tu-bồ-đề! Nhược tam thiên đại thiên thế giới trung sở hữu chư Tu-di sơn vương, như thị đẳng thất bảo tụ, hữu nhân trì dụng bố thí. Nhược nhân dĩ thử Bát-nhã ba-la-mật kinh, nãi chí tứ cú kệ đẳng, thọ trì độc tụng vị tha nhân thuyết, ư tiền phước đức bá phần bất cập nhất, bá thiên vạn ức phần, nãi chí toán số thí dụ sở bất năng cập."],["p","“Tu-bồ-đề! Ư ý vân hà? Nhữ đẳng vật vị Như Lai tác thị niệm: Ngã đương độ chúng sanh. Tu-bồ-đề! Mạc tác thị niệm."],["p","“Hà dĩ cố? Thật vô hữu chúng sanh Như Lai độ giả. Nhược hữu chúng sanh Như Lai độ giả, Như Lai tắc hữu ngã, nhân, chúng sanh, thọ giả."],["p","“Tu-bồ-đề! Như Lai thuyết hữu ngã giả tức phi hữu ngã, nhi phàm phu chi nhân dĩ vi hữu ngã."],["p","“Tu-bồ-đề! Phàm phu giả, Như Lai thuyết tức phi phàm phu."],["p","“Tu-bồ-đề! Ư ý vân hà? Khả dĩ tam thập nhị tướng quan Như Lai phủ?”"],["p","Tu-bồ-đề ngôn: “Như thị, như thị. Dĩ tam thập nhị tướng quan Như Lai.”"],["p","Phật ngôn: “Tu-bồ-đề! Nhược dĩ tam thập nhị tướng quan Như Lai giả, Chuyển Luân Thánh vương tắc thị Như Lai.”"],["p","Tu-bồ-đề bạch Phật ngôn: “Thế Tôn, như ngã giải Phật sở thuyết nghĩa, bất ưng dĩ tam thập nhị tướng quan Như Lai.”"],["p","Nhĩ thời Thế Tôn nhi thuyết kệ ngôn:"],["p","“Nhược dĩ sắc kiến ngã, Dĩ âm thanh cầu ngã. Thị nhân hành tà đạo, Bất năng kiến Như Lai.”"],["p","“Tu-bồ-đề! Nhữ nhược tác thị niệm:"],["p","Như Lai bất dĩ cụ túc tướng cố đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề."],["p","Tu-bồ-đề! Mạc tác thị niệm: Như Lai bất dĩ cụ túc tướng cố đắc A-nậu-đa-la Tam-miệu Tam-bồ-đề."],["p","“Tu-bồ-đề! Nhược tác thị niệm: Phát A-nậu-đa-la Tam-miệu Tam-bồ-đề giả thuyết chư pháp đoạn diệt tướng. Mạc tác thị niệm."],["p","“Hà dĩ cố? Phát A-nậu-đa-la Tam-miệu Tam-bồ-đề tâm giả, ư pháp bất thuyết đoạn diệt tướng."],["p","“Tu-bồ-đề! Nhược Bồ Tát dĩ mãn Hằng hà sa đẳng thế giới thất bảo bố thí."],["p","Nhược phục hữu nhân tri nhất thiết pháp vô ngã đắc thành ư nhẫn. Thử Bồ Tát thắng tiền Bồ Tát sở đắc công đức. Hà dĩ cố? Dĩ chư Bồ Tát bất thọ phước đức cố.”"],["p","“Tu-bồ-đề bạch Phật ngôn: “Thế Tôn! Vân hà Bồ Tát bất thọ phước đức?”"],["p","“Tu-bồ-đề! Bồ Tát sở tác phước đức bất ưng tham trước. Thị cố thuyết bất thọ phước đức."],["p","“Tu-bồ-đề! Nhược hữu nhân ngôn Như Lai nhược lai, nhược khứ, nhược tọa, nhược ngọa, thị nhân bất giải ngã sở thuyết nghĩa. Hà dĩ cố? Như Lai giả, vô sở tùng lai diệc vô sở khứ, cố danh Như Lai."],["p","“Tu-bồ-đề! Nhược thiện nam tử, thiện nữ nhân dĩ tam thiên đại thiên thế giới toái vi vi trần. Ư ý vân hà? Thị vi trần chúng ninh vi đa phủ?”"],["p","“Thậm đa, Thế Tôn. Hà dĩ cố? Nhược thị vi trần chúng thật hữu giả, Phật tắc bất thuyết thị vi trần chúng."],["p","“Sở dĩ giả hà? Phật thuyết vi trần chúng tức phi vi trần chúng, thị danh vi trần chúng."],["p","“Thế Tôn! Như Lai sở thuyết tam thiên đại thiên thế giới tức phi thế giới, thị danh thế giới."],["p","“Hà dĩ cố? Nhược thế giới thật hữu giả, tức thị nhất hiệp tướng. Như Lai thuyết nhất hiệp tướng tức phi nhất hiệp tướng, thị danh nhất hiệp tướng.”"],["p","“Tu-bồ-đề! Nhất hiệp tướng giả tức thị bất khả thuyết. Đản phàm phu chi nhân tham trước kỳ sự."],["p","“Tu-bồ-đề! Nhược nhân ngôn Phật thuyết ngã kiến, nhân kiến, chúng sanh kiến, thọ giả kiến. Tu-bồ-đề! Ư ý vân hà?"],["p","Thị nhân giải ngã sở thuyết nghĩa phủ?”"],["p","“Thế Tôn! Thị nhân bất giải Như Lai sở thuyết nghĩa."],["p","“Hà dĩ cố? Thế Tôn thuyết ngã kiến, nhân kiến, chúng sanh kiến, thọ giả kiến tức phi ngã kiến, nhân kiến, chúng sanh kiến, thọ giả kiến, thị danh ngã kiến, nhân kiến, chúng sanh kiến, thọ giả kiến.”"],["p","“Tu-bồ-đề! Phát A-nậu-đa-la Tam-miệu Tam-bồ-đề tâm giả, ư nhất thiết pháp ưng như thị tri, như thị kiến, như thị tín giải, bất sanh pháp tướng."],["p","“Tu-bồ-đề! Sở ngôn pháp tướng giả, Như Lai thuyết tức phi pháp tướng, thị danh pháp tướng."],["p","“Tu-bồ-đề! Nhược hữu nhân dĩ mãn vô lượng a-tăng-kỳ thế giới thất bảo trì dụng bố thí. Nhược hữu thiện nam tử, thiện nữ nhân phát Bồ-đề tâm giả, trì ư thử kinh, nãi chí tứ cú kệ đẳng, thọ trì độc tụng, vị nhân diễn thuyết, kỳ phước thắng bỉ."],["p","“Vân hà vị nhân diễn thuyết? Bất thủ ư tướng, như như bất động. Hà dĩ cố?"],["v",["Nhất thiết hữu vi pháp,","Như mộng ảo bào ảnh,","Như lộ diệc như điển,","Ưng tác như thị quán.”"]],["p","Phật thuyết thị kinh dĩ, Trưởng lão Tu-bồ-đề, cập chư tỳ-kheo, tỳ-kheo ni, ưu-bà-tắc, ưu-bà-di, nhất thiết thế gian, thiên, nhân, a-tu-la... văn Phật sở thuyết giai đại hoan hỷ, tín thọ phụng hành."],["p","Nam mô Bát Nhã Hội Thượng Phật Bồ Tát"],["p","Ma Ha Tát. (3 lần)"]],"p":"Phần Dịch Âm"},{"t":"Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh","b":[["p","Quán Tự Tại Bồ Tát hành thâm Bát Nhã Ba La Mật Đa thời, chiếu kiến ngũ uẩn giai không độ nhứt thiết khổ ách."],["p","Xá Lợi Tử! Sắc bất dị không, không bất dị sắc, sắc tức thị không, không tức thị sắc, thọ, tưởng, hành, thức diệc phục như thị."],["p","Xá Lợi Tử! Thị chư pháp không tướng, bất sanh, bất diệt, bất cấu, bất tịnh, bất tăng, bất giảm. Thị cố không trung vô sắc, vô thọ, tưởng, hành, thức, vô nhãn, nhĩ, tỷ, thiệt, thân, ý, vô sắc, thinh, hương, vị, xúc, pháp, vô nhãn giới, nãi chí vô ý thức giới, vô vô minh diệc vô vô minh tận, nãi chí vô lão tử diệc, vô lão tử tận, vô khổ, tập, diệt, đạo, vô trí diệc vô đắc. Dĩ vô sở đắc cố, Bồ đề tát đỏa y Bát Nhã Ba La Mật Đa cố, tâm vô quái ngại, vô quái ngại cố, vô hữu khủng bố, viễn ly điên đảo mộng tưởng cứu cánh Niết Bàn. Tam thế chư Phật y Bát Nhã Ba La Mật Đa cố, đắc a nậu đa la tam miệu tam bồ đề. Cố tri Bát Nhã Ba La Mật Đa, thị đại thần chú, thị đại minh chú, thị vô thượng chú, thị vô đẳng đẳng chú, năng trừ nhứt thiết khổ, chơn thật bất hư."],["v",["Cố thuyết Bát Nhã Ba La Mật Đa chú.","Tức thuyết chú viết:"]],["p","“Yết đế yết đế, ba la yết đế, ba la tăng yết đế, bồ đề tát bà ha.” (3 lần)"],["p","VÃNG SANH QUYẾT ĐỊNH CHÂN NGÔN"],["p","Nam mô a di đa bà dạ, đa tha già đa dạ, đa địa dạ tha. A di rị đô bà tỳ, a di rị đa tất đam bà tỳ, a di rị đa tỳ ca lan đế, a di rị đa tỳ ca lan đa, dà di nị dà dà na, chỉ đa ca lệ ta bà ha. (3 lần)"],["v",["KIM CANG CHÂN NGÔN","Án, hô rô, hô rô, xả duệ, mục khế, tá ha. (7 lần)","PHỔ HỒI HƯỚNG CHÂN NGÔN"]],["p","Án, ta ma ra, ta ma ra, di ma nẵng tát cáp ra, ma ha thính cáp ra hồng. (3 lần)"],["p","Nhứt hồi hướng: Chân như thiệt tế tâm tâm khế hiệp."],["p","Nhị hồi hướng: Vô thượng Phật quả, bồ đề niệm niệm viên mãn."],["p","Tam hồi hướng: Pháp giới nhứt thiết chúng sanh đồng sanh Tịnh Độ."],["h","Tán Viết"],["v",["Kim cang công đức","Diệu lý nan lương","Như Lai vị chúng quảng tuyên dương","Thọ thí ngộ chân thường","Dĩ chư hoa hương","Phổ tán Pháp Trung Vương.","Nam mô Kỳ Viên Hội Thượng Phật Bồ Tát"]],["p","Ma Ha Tát. (3 lần)"]],"p":"Phần Dịch Âm"},{"t":"Tán Phật","b":[["v",["A Di Đà Phật thân kim sắc","Tướng hảo quang minh vô đẳng luân","Bạch hào uyển chuyển ngũ tu di","Cám mục trừng thanh tứ đại hải","Quang trung hóa Phật vô số ức","Hóa Bồ Tát chúng diệc vô biên","Tứ thập bát nguyện độ chúng sanh","Cửu phẩm hàm linh đăng bỉ ngạn."]],["p","Nam mô Tây Phương Cực Lạc Thế Giới Đại Từ Đại Bi A Di Đà Phật."],["p","Nam mô A Di Đà Phật. (21 lần)"],["p","Nam mô Đại Bi Quán Thế Âm Bồ Tát. (3 lần) Nam mô Đại Thế Chí Bồ Tát. (3 lần)"],["v",["Nam mô Địa Tạng Vương Bồ Tát. (3 lần)","Nam mô Thanh Tịnh Đại Hải Chúng Bồ","Tát. (3 lần)"]]],"p":"Phần Dịch Âm"},{"t":"Phúng Kinh","b":[["v",["Phúng kinh công đức thù thắng hạnh,","Vô biên thắng phước giai hồi hướng,","Phổ nguyện pháp giới chư chúng sanh,","Tốc vãng vô lượng quang Phật sát."]],["v",["Nguyện tiêu tam chướng trừ phiền não,","Nguyện đắc trí huệ chơn minh liễu,","Phổ nguyện tội chướng tất tiêu trừ,","Thế thế thường hành Bồ tát đạo."]],["v",["Nguyện sanh Tây Phương Tịnh Độ trung,","Cửu phẩm Liên hoa vi phụ mẫu,","Hoa khai kiến Phật ngộ vô sanh,","Bất thối Bồ tát vi bạn lữ."]],["v",["Nguyện dĩ thử công đức,","Phổ cập ư nhứt thiết,","Ngã đẳng dữ chúng sanh,","Giai cộng thành Phật đạo."]]],"p":"Phần Dịch Âm"},{"t":"Tam Quy Y","b":[["p","Tự quy y Phật, đương nguyện chúng sanh, thể giai đại đạo, phát vô thượng tâm. (1 lạy)"],["p","Tự quy y Pháp, đương nguyện chúng sanh, thâm nhập kinh tạng, trí huệ như hải. (1 lạy)"],["p","Tự quy y Tăng, đương nguyện chúng sanh, thống lý đại chúng, nhất thiết vô ngại. (1 lạy)"]],"p":"Phần Dịch Âm"},{"t":"Hồi Hướng","b":[["v",["Nguyện đem công đức nầy","Hướng về khắp tất cả","Đệ tử và chúng sanh","Đều trọn thành phật đạo."]]],"p":"Phần Dịch Âm"}]};
